BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q181', '計測・制御に関する理論', 'アナログ信号とデジタル信号の違いに関する記述として、最も適切なものはどれか。', NULL::text, '["アナログ信号は連続的に変化する物理量をそのまま表現し、デジタル信号は一定間隔で区切った離散的な数値の並びとして表現する。", "アナログ信号は0と1のみで構成される信号であり、デジタル信号は温度や音のような物理量の変化をそのまま連続的な波形として表現する仕組みである。", "アナログ信号とデジタル信号はどちらも連続的な波形で表現されるが、電圧の範囲が異なる。", "アナログ信号は音や光には使えず、デジタル信号だけがセンサーの出力を表現できる。"]', 0, '[0]', 'single', '{"asked": "アナログ信号とデジタル信号の違いについて問うている。", "point": "値が切れ目なく連続するならアナログ、一定間隔で区切った数値の並びにするならデジタルと判断する。", "kid": "アナログは滑らかに変わる量そのもの、デジタルはそれを区切って数字にしたもの。", "eg": "温度計の水銀柱の高さ(アナログ)を、1分おきに「23.4℃」と数字で記録していく(デジタル)ようなもの。", "terms": [["アナログ信号", "時間とともに切れ目なく連続的に変化する物理量そのものを表す信号"], ["デジタル信号", "値を一定間隔で区切り、離散的な数値の並びとして表す信号"], ["標本化(サンプリング)", "連続する信号を一定の時間間隔で区切って値を取り出す処理"]], "think": "コンピュータは0と1の組み合わせでしか値を扱えないため、温度や音のような連続量(アナログ信号)をそのまま計算処理することはできない。そこで一定の時間間隔で値を取り出し(標本化)、それぞれを数値に変換する(量子化)ことで、コンピュータが扱える離散的な数値の並び、つまりデジタル信号に変換してから処理する。", "opt": ["正解。アナログ信号は温度や音圧のような物理量を切れ目なく連続的に表す。デジタル信号はそれを一定の時間間隔で区切り、決まった精度の数値として並べたものである。", "アナログとデジタルの説明が入れ替わっている。0と1の組み合わせで値を表すのはデジタル信号のほうである。", "デジタル信号は連続的な波形ではなく、離散的な数値の並びである点が異なる。", "センサーはまず物理量をアナログ信号として出力することが多く、それをデジタル信号に変換して処理するのが一般的な流れである。アナログ信号自体が使えないわけではない。"]}'),
  ('ap-core-q182', '計測・制御に関する理論', 'アナログ信号をデジタル信号に変換する処理の順序に関する記述として、最も適切なものはどれか。', NULL::text, '["標本化で時間軸を区切って値を取り出し、量子化でその値を決まった段階数に丸め、符号化で2進数に変換するという順番で進む。", "量子化が時間軸を一定間隔に区切って値を取り出し、標本化はその取り出した値をそのまま2進数の符号に変換するという順番で進む。", "標本化と量子化はどちらも時間軸を区切る処理であり、値を数値に丸める処理は符号化が担う。", "符号化で時間軸を先に区切り、その後に標本化で2進数に変換するという順番で進む。"]', 0, '[0]', 'single', '{"asked": "アナログ信号をデジタル信号に変換する際の手順(A/D変換)について問うている。", "point": "先に時間軸を区切るのが標本化、その後に値を数値に丸めるのが量子化と覚える。", "kid": "アナログ信号をデジタル化するには、時間を区切って値を取り出し(標本化)、その値を決まった段階の数値に丸め(量子化)、最後に0と1の符号にする(符号化)という順番で進む。", "eg": "写真をスキャンするとき、まず一定間隔でマス目に区切り(標本化)、各マスの色を決まった色数の中から一番近い色に置き換える(量子化)のと同じ考え方。", "terms": [["標本化(サンプリング)", "一定の時間間隔で信号の値を取り出す処理"], ["量子化", "取り出した値を、あらかじめ決めた段階数の中で最も近い数値に丸める処理"], ["符号化", "量子化した数値を0と1の並び(2進数)に変換する処理"]], "think": "アナログ信号は値の種類も時間も切れ目なく連続しているため、そのままではコンピュータが扱える有限個の数値に対応づけられない。そこでまず時間軸を一定間隔で区切って値を取り出し(標本化)、次にその値を有限個の段階のどれかに丸め(量子化)、最後にその段階番号を2進数の符号に変換する(符号化)。この3段階を経て初めて、連続量が有限桁のデジタル信号になる。", "opt": ["正解。標本化で時間軸を区切って値を取り出し、量子化でその値を段階数に丸め、符号化で2進数に変換するという順番で進む。", "標本化と量子化の役割が入れ替わっている。時間軸を区切るのは標本化であり、量子化は値を段階に丸める処理である。", "値を数値に丸めるのは量子化の役割であり、符号化は量子化された段階番号を2進数の符号に変換する処理である。", "時間軸を区切るのは標本化であり、符号化はその後段で2進数化を担う処理である。順番が入れ替わっている。"]}'),
  ('ap-core-q183', '計測・制御に関する理論', 'フィードバック制御の考え方に関する記述として、最も適切なものはどれか。', NULL::text, '["制御対象の出力を測定し、目標値との差(偏差)を求めて、その差を無くすように入力側を修正することを繰り返す制御方式である。", "あらかじめ外乱の影響を予測しておき、出力をまったく測定することなく、その予測結果だけに基づいて入力側を事前に調整しておく制御方式である。", "制御対象の内部構造を数式でモデル化し、シミュレーションのみで最適な入力を一度だけ算出する制御方式である。", "目標値を固定せず、外乱の大きさに応じて目標値そのものを変化させ続ける制御方式である。"]', 0, '[0]', 'single', '{"asked": "フィードバック制御の考え方について問うている。", "point": "出力(結果)を測定して目標値と比べ、その差を無くすように入力側を修正し続けるならフィードバック制御と判断する。", "kid": "今の結果を見てから、目標とのズレを直していく制御の方法。", "eg": "シャワーの温度をぬるいと感じたら蛇口をひねって熱いほうに調整し、また温度を確かめてさらに調整する、を繰り返す。", "terms": [["目標値", "制御によって実現したい値"], ["制御量(出力)", "実際にセンサーなどで測定される、制御対象の現在の状態"], ["偏差", "目標値と制御量(出力)の差"]], "think": "フィードバック制御では、まず制御対象の出力をセンサーで測定し、その値を目標値と比較して偏差(ズレ)を求める。その偏差を無くす方向に入力(操作量)を調整し、また出力を測定する、というループを繰り返す。結果を測定してから修正するという順番のため、外乱が発生してから実際に補正が効くまでに必ず遅れが生じる。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"arrow183\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><rect x=\"8\" y=\"45\" width=\"58\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"37\" y=\"65\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">目標値</text><line x1=\"66\" y1=\"61\" x2=\"86\" y2=\"61\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow183)\"/><circle cx=\"102\" cy=\"61\" r=\"16\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"102\" y=\"65\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">偏差</text><line x1=\"118\" y1=\"61\" x2=\"149\" y2=\"61\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow183)\"/><rect x=\"150\" y=\"45\" width=\"58\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"179\" y=\"65\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">制御器</text><line x1=\"208\" y1=\"61\" x2=\"239\" y2=\"61\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow183)\"/><rect x=\"240\" y=\"45\" width=\"70\" height=\"32\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"275\" y=\"65\" font-size=\"11\" fill=\"#e8eaf0\" text-anchor=\"middle\">制御対象</text><line x1=\"310\" y1=\"61\" x2=\"329\" y2=\"61\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow183)\"/><text x=\"332\" y=\"58\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"end\">出力</text><line x1=\"275\" y1=\"77\" x2=\"275\" y2=\"114\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><line x1=\"275\" y1=\"114\" x2=\"102\" y2=\"114\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><line x1=\"102\" y1=\"114\" x2=\"102\" y2=\"78\" stroke=\"#6ab08d\" stroke-width=\"1.5\" marker-end=\"url(#arrow183)\"/><text x=\"189\" y=\"130\" font-size=\"10\" fill=\"#6ab08d\" text-anchor=\"middle\">センサーで出力を測定して比較へ戻す</text></svg>", "opt": ["正解。出力を測定して目標値と比べ、その差(偏差)を無くす方向に入力を修正し続けるのがフィードバック制御である。", "これはフィードフォワード制御の説明である。フィードバック制御は出力を測定してから修正する点が異なる。", "数式モデルによる一度きりの算出ではなく、出力の測定と修正を繰り返し続ける点がフィードバック制御の特徴である。", "フィードバック制御で修正されるのは入力(操作量)であり、目標値そのものは通常固定されたままである。"]}'),
  ('ap-core-q184', '計測・制御に関する理論', 'フィードバック制御において、外乱が発生してから実際に補正が効き始めるまでに遅れが生じる理由として、最も適切なものはどれか。', NULL::text, '["外乱の影響が出力に現れ、それをセンサーで測定し、目標値と比較して修正指令を出すまでの一連の手順に時間がかかるため。", "フィードバック制御はそもそもセンサーを使わない方式であるため、外乱の発生そのものを検知する手段が用意されていないため。", "制御器の計算速度が遅いことだけが原因であり、測定や比較の手順自体には時間はかからないため。", "目標値を毎回人間が入力し直す必要があり、その入力作業の時間がそのまま遅れになるため。"]', 0, '[0]', 'single', '{"asked": "フィードバック制御において、外乱が発生してから実際に補正が効くまでに遅れが生じる理由について問うている。", "point": "結果を測定してから修正するので、測定・比較・修正という手順を経る分だけ必ず遅れが生じると考える。", "kid": "フィードバック制御は「ズレが起きたのを確認してから直す」方式なので、直り始めるまでに一呼吸おいた遅れが出る。", "eg": "お風呂の温度がぬるくなったと気づいてから蛇口をひねるまでの間、体は少しの間ぬるいお湯を浴び続けている。", "terms": [["外乱", "目標値からのズレを引き起こす、制御対象の外部からの予期しない影響"], ["むだ時間", "入力を変えてから出力にその影響が現れるまでの時間差"]], "think": "フィードバック制御は、出力を測定し、目標値と比較して偏差を求め、その偏差に応じて入力を修正する、という順番で動く。外乱が発生した直後は、まだその影響が出力に現れておらず偏差も検出されていないため、修正が始まらない。出力の変化がセンサーで検出され、比較・演算を経て初めて修正の指令が出るため、外乱の発生から実際の補正が効き始めるまでの間に、測定・比較・演算という手順の分だけ遅れが生じる。", "opt": ["正解。出力への影響が現れてから、測定・比較・修正指令という手順を経るまでの時間が遅れの原因である。", "フィードバック制御はセンサーで出力を測定することが前提の方式であり、センサーを使わないという記述が誤りである。", "遅れの原因は計算速度だけでなく、測定・比較という手順そのものにも時間がかかる点にある。", "フィードバック制御では目標値は通常あらかじめ設定されており、都度人間が入力し直す必要があるとは限らない。"]}'),
  ('ap-core-q185', '計測・制御に関する理論', '次のうち、フィードバック制御に該当する仕組みとして、最も適切なものはどれか。', NULL::text, '["エアコンが室温センサーで測定した現在の室温と設定温度の差を常に確認し、その差に応じて冷房・暖房の強さを調整し続ける仕組み。", "灌漑システムが、あらかじめ決めた時刻になったら、土壌の湿り気をまったく測定することなく、毎回同じ一定時間だけ散水を行う仕組み。", "オーブンが、あらかじめ設定した調理時間が経過したら、庫内の温度を測定せずに自動的に加熱を停止する仕組み。", "照明が、あらかじめ決めたタイマー時刻になったら、周囲の明るさを測定せずに点灯・消灯する仕組み。"]', 0, '[0]', 'single', '{"asked": "身近な仕組みの中からフィードバック制御に該当する例を選ぶことを問うている。", "point": "現在の状態を測定し、目標との差に応じて動作を変え続けている例ならフィードバック制御と判断する。", "kid": "「測って、比べて、直す」を繰り返している仕組みを探す。", "eg": "エアコンが室温センサーで今の温度を測り、設定温度より高ければ冷房を強め、近づけば弱めるという動きを繰り返す。", "terms": [["室温センサー", "現在の室温を検出し電気信号に変換する機器"], ["オープンループ制御", "出力を測定せず、あらかじめ決めた条件だけで動作する制御の考え方"]], "think": "四つの候補それぞれについて、現在の出力を測定しているか、その測定結果に基づいて入力を変え続けているかを確認する。測定と比較を経ずに、あらかじめ決めたタイミングや条件だけで動作する仕組みは、結果を見ずに動くためフィードバック制御には該当しない。", "opt": ["正解。室温という出力を測定し、目標値(設定温度)との差に応じて入力(冷房・暖房の強さ)を調整し続けている点がフィードバック制御にあたる。", "土壌の湿り気(出力)を測定せず、決めた時刻・時間だけで動作しており、結果を見て修正する仕組みになっていない。", "庫内温度(出力)を測定せず、あらかじめ決めた時間の経過だけで停止しており、結果を見て修正する仕組みになっていない。", "周囲の明るさ(出力)を測定せず、あらかじめ決めた時刻だけで動作しており、結果を見て修正する仕組みになっていない。"]}'),
  ('ap-core-q186', '計測・制御に関する理論', 'フィードフォワード制御の考え方に関する記述として、最も適切なものはどれか。', NULL::text, '["出力を測定せず、外乱の発生や影響をあらかじめ予測して、結果に現れる前に入力側を調整する制御方式である。", "出力を測定し、目標値との差(偏差)を求めて、その差を無くす方向へ入力を修正することを繰り返す制御方式である。", "外乱の影響が出力に現れた後で、その大きさを測定してから入力を修正する制御方式である。", "目標値と制御対象の内部状態を常に一致させるように制御器を再設計し続ける制御方式である。"]', 0, '[0]', 'single', '{"asked": "フィードフォワード制御とフィードバック制御の違いについて問うている。", "point": "結果を見てから直すならフィードバック、結果が出る前に予測して先回りで直すならフィードフォワードと判断する。", "kid": "フィードフォワード制御は、外乱の影響が出力に表れる前に、あらかじめその影響を見込んで入力側を調整しておく方式。", "eg": "天気予報で雨が降ると分かった時点で、濡れてから傘を探すのではなく、家を出る前に傘を用意しておく。", "terms": [["外乱", "制御対象の外部からの予期しない影響"], ["オープンループ制御", "出力を測定せず、入力側の調整だけで完結する制御の考え方。フィードフォワード制御はこの一種"]], "think": "フィードバック制御は出力を測定して偏差を検出してから修正するため、外乱が実際に結果へ影響してから直すまでに手順の分だけ遅れが生じる。フィードフォワード制御は、外乱そのものを検知するか、あらかじめ影響を見込んでおき、結果に現れる前に入力側で先に補正をかける。そのため理論上は遅れを小さくできるが、出力を測定して確認する仕組みを持たないため、予測が外れた場合や見込んでいない外乱に対しては誤差が残ったままになりやすい。", "vs": "フィードバック制御は出力(結果)を測定してから偏差を無くす方向に入力を修正するのに対し、フィードフォワード制御は出力を測定せず、外乱の発生を検知した時点や事前の予測に基づいて入力を先に調整する。フィードフォワード制御は結果を待たない分だけ遅れが小さくなるが、予測が外れると誤差を直接修正する手段を持たない。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><defs><marker id=\"arrow186\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#8892a4\"/></marker></defs><text x=\"8\" y=\"18\" font-size=\"10\" fill=\"#c9a04a\" text-anchor=\"start\">フィードフォワード制御(先読みで調整)</text><rect x=\"8\" y=\"28\" width=\"66\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"41\" y=\"45\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">外乱の予測</text><line x1=\"74\" y1=\"41\" x2=\"95\" y2=\"41\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/><rect x=\"96\" y=\"28\" width=\"50\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"121\" y=\"45\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">制御器</text><line x1=\"146\" y1=\"41\" x2=\"167\" y2=\"41\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/><rect x=\"168\" y=\"28\" width=\"64\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"200\" y=\"45\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">制御対象</text><line x1=\"232\" y1=\"41\" x2=\"252\" y2=\"41\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/><text x=\"255\" y=\"45\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\">出力</text><text x=\"332\" y=\"41\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"end\">戻り経路なし</text><text x=\"8\" y=\"80\" font-size=\"10\" fill=\"#60a5fa\" text-anchor=\"start\">フィードバック制御(結果を見て調整)</text><rect x=\"8\" y=\"90\" width=\"50\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><text x=\"33\" y=\"107\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">目標値</text><line x1=\"58\" y1=\"103\" x2=\"76\" y2=\"103\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/><circle cx=\"90\" cy=\"103\" r=\"13\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"90\" y=\"106\" font-size=\"8.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">偏差</text><line x1=\"103\" y1=\"103\" x2=\"122\" y2=\"103\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/><rect x=\"123\" y=\"90\" width=\"50\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"148\" y=\"107\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">制御器</text><line x1=\"173\" y1=\"103\" x2=\"192\" y2=\"103\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/><rect x=\"193\" y=\"90\" width=\"64\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"225\" y=\"107\" font-size=\"9.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">制御対象</text><line x1=\"257\" y1=\"103\" x2=\"277\" y2=\"103\" stroke=\"#8892a4\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/><text x=\"280\" y=\"107\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\">出力</text><line x1=\"225\" y1=\"116\" x2=\"225\" y2=\"140\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><line x1=\"225\" y1=\"140\" x2=\"90\" y2=\"140\" stroke=\"#6ab08d\" stroke-width=\"1.5\"/><line x1=\"90\" y1=\"140\" x2=\"90\" y2=\"117\" stroke=\"#6ab08d\" stroke-width=\"1.5\" marker-end=\"url(#arrow186)\"/></svg>", "opt": ["正解。出力を測定せず、外乱の影響が結果に現れる前に、あらかじめの予測に基づいて入力側を先に調整するのがフィードフォワード制御である。", "これはフィードバック制御の説明である。出力を測定して偏差を無くす方向に修正するのはフィードバックの特徴である。", "出力に影響が現れた後で測定して修正するのはフィードバック制御の順序であり、フィードフォワード制御は影響が現れる前に調整する点が異なる。", "フィードフォワード制御は入力側をあらかじめ調整する方式であり、制御器自体を作り直し続けるものではない。"]}'),
  ('ap-core-q187', '計測・制御に関する理論', 'フィードバック制御とフィードフォワード制御を組み合わせて使うことがある理由として、最も適切なものはどれか。', NULL::text, '["フィードフォワード制御で予測できる外乱の影響を先に大まかに打ち消し、残った誤差や未知の外乱をフィードバック制御で結果を見ながら細かく修正するため。", "フィードフォワード制御だけを使えば理論上は誤差が完全にゼロになるとされているため、フィードバック制御は発生した誤差の記録用としてのみ使われるため。", "フィードバック制御だけで十分な速さで補正できるため、フィードフォワード制御は電力消費を減らす目的だけで追加されるため。", "両方を組み合わせることで、目標値そのものを制御の途中で自動的に書き換えられるようにするため。"]', 0, '[0]', 'single', '{"asked": "フィードバック制御とフィードフォワード制御を組み合わせて使う理由について問うている。", "point": "フィードフォワードで素早く粗く補正し、フィードバックで測定に基づき細かく仕上げる、という役割分担なら組み合わせが有効と判断する。", "kid": "先読みで大まかに直しておき(フィードフォワード)、それでも残ったズレを結果を見ながら細かく直す(フィードバック)。", "eg": "料理で、レシピ通りの分量を先に量って入れておき(フィードフォワード)、味見をしながら塩加減を微調整する(フィードバック)。", "terms": [["定常偏差", "時間が経っても無くならずに残り続ける偏差"]], "think": "フィードフォワード制御だけでは、予測していない外乱や予測の誤差に対応する手段がなく、誤差が残ったまま補正されない。フィードバック制御だけでは、外乱の影響が出力に現れてから修正が始まるため、修正が効き始めるまでの遅れが避けられない。そこで、予測できる外乱の影響はフィードフォワードで先に大まかに打ち消しておき、予測しきれずに残った誤差や未知の外乱はフィードバックで結果を見ながら細かく修正する、という役割分担にすることで、両方の弱点を補い合える。", "opt": ["正解。予測できる外乱はフィードフォワードで先に打ち消し、残った誤差や未知の外乱はフィードバックで結果を見ながら細かく修正するという役割分担が組み合わせの目的である。", "フィードフォワード制御は予測に基づく方式であり、予測が外れた分の誤差は残る。フィードバック制御はその誤差を修正する役割を持ち、記録用ではない。", "フィードバック制御は結果を見てから修正するため遅れが生じる。フィードフォワード制御はその遅れを補う目的で組み合わされ、電力消費の削減が主目的ではない。", "組み合わせの目的は誤差の打ち消しであり、目標値そのものを自動的に書き換えるものではない。"]}'),
  ('ap-core-q188', '計測・制御に関する理論', '制御の応答特性における「オーバーシュート」の説明として、最も適切なものはどれか。', NULL::text, '["出力が目標値に近づく過程で、目標値を一度超えてから戻ってくる現象のことである。", "出力が目標値にまったく到達せず、目標値より低い値で止まってしまう現象のことである。", "出力が目標値の周りで小刻みな振動を止めないまま、いつまでも収束しない現象のことである。", "出力が目標値に到達するまでに、途中で複数回停止と再開を繰り返す現象のことである。"]', 0, '[0]', 'single', '{"asked": "制御の応答特性における「オーバーシュート」について問うている。", "point": "出力が目標値に到達する過程で、目標値を一度超えてから戻る現象ならオーバーシュートと判断する。", "kid": "目標値に向かっていく途中で、勢い余って一度行き過ぎてしまうこと。", "eg": "エアコンの設定温度に近づけようとして、一度設定温度より冷えすぎてから戻ってくるような動き。", "terms": [["整定時間", "出力が目標値の近くに収まって落ち着くまでにかかる時間"], ["応答特性", "目標値を与えてから出力がどのように変化して目標値に近づいていくかという性質"]], "think": "制御器が偏差(目標値とのズレ)を無くそうとして入力を強く補正すると、出力は目標値に向かって速く近づく。しかし補正の効き目が出力に反映されるまでには遅れがあるため、目標値に到達した時点でもまだ補正の勢いが残っており、出力はそのまま目標値を通り過ぎてしまう。行き過ぎたことを検知して逆方向に補正がかかり、出力は目標値の方へ戻ってくる。この「行き過ぎてから戻る」動きがオーバーシュートである。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><line x1=\"30\" y1=\"20\" x2=\"30\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"30\" y1=\"130\" x2=\"320\" y2=\"130\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"30\" y1=\"60\" x2=\"320\" y2=\"60\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><text x=\"322\" y=\"63\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"start\">目標値</text><path d=\"M30,130 C70,45 95,18 140,35 C175,50 195,72 220,63 C250,57 265,61 320,60\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.8\"/><circle cx=\"140\" cy=\"35\" r=\"3\" fill=\"#c47070\"/><line x1=\"140\" y1=\"35\" x2=\"140\" y2=\"60\" stroke=\"#c47070\" stroke-width=\"1\" stroke-dasharray=\"2,2\"/><text x=\"148\" y=\"30\" font-size=\"9.5\" fill=\"#c47070\" text-anchor=\"start\">オーバーシュート</text><text x=\"15\" y=\"134\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"end\">0</text><text x=\"175\" y=\"145\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">時間</text></svg>", "opt": ["正解。目標値に近づく途中で一度目標値を超え、その後戻ってくる現象がオーバーシュートである。", "目標値に到達しないまま低い値で止まるのは定常偏差が残っている状態であり、オーバーシュートとは異なる現象である。", "振動がいつまでも収まらないのは不安定な状態であり、一度行き過ぎてから戻るオーバーシュートとは区別される。", "停止と再開を繰り返す動きは制御の応答特性として一般的な説明ではなく、オーバーシュートの定義ではない。"]}'),
  ('ap-core-q189', '計測・制御に関する理論', '制御の応答を速くすることとオーバーシュートの大きさの関係として、最も適切なものはどれか。', NULL::text, '["応答を速くするために補正を強くするほど、目標値到達時点でも補正の勢いが残りやすくなり、オーバーシュートは大きくなりやすい。", "応答を速くするために補正を強くするほど、目標値到達時点での勢いはむしろきれいに打ち消され、オーバーシュートは必ず小さくなる。", "応答の速さとオーバーシュートの大きさの間には、一般に関係が無く、互いに独立して調整できる。", "応答を遅くするほど、目標値に到達するまでの間に補正の勢いが蓄積し続け、オーバーシュートは大きくなりやすい。"]', 0, '[0]', 'single', '{"asked": "制御の応答を速くすることとオーバーシュートの関係について問うている。", "point": "補正を強くして応答を速めるほど、行き過ぎる勢いも大きくなりオーバーシュートが大きくなりやすいと考える。", "kid": "速く目標値に近づけようとするほど、勢いがつきすぎて行き過ぎやすくなる。", "eg": "自転車で早く止まろうとブレーキを強くかけすぎると、逆に体が前に大きく傾いてしまうのと似ている。", "terms": [["ゲイン", "偏差に対して補正をどれだけ強くかけるかを決める倍率"]], "think": "応答を速くするには、偏差に対する補正の効き目(制御の強さ)を大きくする必要がある。補正を強くすると出力は目標値に速く近づくが、出力の変化が制御器に反映されるまでの遅れのために、目標値に到達した時点でもまだ強い補正の勢いが残っている。その勢いの分だけ出力は目標値を超えて進んでしまうため、応答を速くするほどオーバーシュートは大きくなりやすい。応答の速さとオーバーシュートの小ささは、一般に両立させにくいトレードオフの関係にある。", "opt": ["正解。補正を強くして応答を速めるほど、目標値到達時点で残る勢いが大きくなり、オーバーシュートも大きくなりやすい。", "補正を強くするほど到達時点の勢いは残りやすく、打ち消されるとは限らない。オーバーシュートが必ず小さくなるわけではない。", "応答を速くする補正の強さとオーバーシュートの大きさは、一般に無関係ではなく、互いに影響し合う関係にある。", "応答を遅くするほど勢いは抑えられる傾向にあり、オーバーシュートは大きくなりにくい。速さと行き過ぎやすさの関係が逆になっている。"]}'),
  ('ap-core-q190', '計測・制御に関する理論', '制御系における「安定」の考え方に関する記述として、最も適切なものはどれか。', NULL::text, '["時間が経つにつれて出力の振動が小さくなり、目標値付近の値に収束していくのであれば、その制御系は安定していると言える。", "出力が一度も目標値からずれることなく、常に目標値と完全に一致し続けるのであれば、その制御系は安定していると言える。", "出力の振動の幅が時間とともにどんどん大きくなり、目標値から限りなく離れていくのであれば、その制御系は安定していると言える。", "制御器の計算処理が高速であれば、出力の振動の有無にかかわらず、その制御系は常に安定していると言える。"]', 0, '[0]', 'single', '{"asked": "制御系における「安定」の考え方について問うている。", "point": "時間が経つにつれて出力の振動が小さくなり、目標値付近に収束していくなら安定と判断する。", "kid": "放っておいても、そのうち目標値の近くに落ち着くかどうか。", "eg": "ブランコを一度押した後、手を離しても揺れ幅がだんだん小さくなって止まるなら安定。逆に揺れ幅がどんどん大きくなっていくなら不安定。", "terms": [["発散", "時間が経つにつれて出力の振動やズレがどんどん大きくなっていくこと"], ["収束", "時間が経つにつれて出力が目標値付近の一定の値に近づいていくこと"]], "think": "制御系にオーバーシュートのような一時的なズレが生じても、その後の補正によって振動の幅が時間とともに小さくなり、最終的に目標値付近の値に落ち着くのであれば、その制御系は安定していると言える。逆に、補正のたびに振動の幅がむしろ大きくなっていき、出力が目標値から際限なく離れていくのであれば、その制御系は不安定であり、そのままでは使い物にならない。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"85\" y=\"14\" font-size=\"10\" fill=\"#6ab08d\" text-anchor=\"middle\">安定(収束する)</text><line x1=\"20\" y1=\"20\" x2=\"20\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"20\" y1=\"140\" x2=\"150\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"20\" y1=\"80\" x2=\"150\" y2=\"80\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><path d=\"M20,130 C35,45 50,20 65,50 C78,72 88,90 98,80 C108,72 116,82 124,80 C132,78 140,80 150,80\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.8\"/><text x=\"255\" y=\"14\" font-size=\"10\" fill=\"#c47070\" text-anchor=\"middle\">不安定(発散する)</text><line x1=\"190\" y1=\"20\" x2=\"190\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"190\" y1=\"140\" x2=\"320\" y2=\"140\" stroke=\"#2a2f3f\" stroke-width=\"1\"/><line x1=\"190\" y1=\"80\" x2=\"320\" y2=\"80\" stroke=\"#8892a4\" stroke-width=\"1\" stroke-dasharray=\"4,3\"/><path d=\"M190,100 C205,50 218,115 230,35 C242,130 255,25 268,145\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.8\"/></svg>", "opt": ["正解。振動の幅が時間とともに小さくなり目標値付近に収束していくことが、安定の判断基準である。", "常に完全に一致し続ける状態を求めているわけではない。振動があっても収束していけば安定と判断できる。", "振動の幅が時間とともに大きくなり目標値から離れていくのは不安定な状態であり、安定の説明ではない。", "計算処理の速さと安定性は別の性質であり、計算が速くても振動が収束しなければ不安定な制御系になり得る。"]}'),
  ('ap-core-q191', '計測・制御に関する理論', 'PID制御を構成する比例(P)・積分(I)・微分(D)それぞれの役割に関する記述として、最も適切なものはどれか。', NULL::text, '["比例(P)は現在の偏差の大きさに応じて補正し、積分(I)は偏差が積み重なった分を無くすように補正し、微分(D)は偏差の変化の速さに応じて早めに補正する。", "比例(P)は偏差の変化の速さに応じて素早く補正し、積分(I)は現在の偏差の大きさに応じて補正し、微分(D)は偏差が積み重なった分を無くすように補正する。", "比例(P)・積分(I)・微分(D)はいずれも同じ計算式で偏差の大きさだけに応じて補正するため、実質的に役割の違いは無い。", "比例(P)は目標値そのものを書き換え、積分(I)はセンサーの測定間隔を調整し、微分(D)はアクチュエーターの種類を切り替える。"]', 0, '[0]', 'single', '{"asked": "PID制御を構成する比例・積分・微分の3つの要素がそれぞれ何を担っているかについて問うている。", "point": "今のズレの大きさに応じて直すのが比例、ズレの積み重なりを直すのが積分、ズレの変化の勢いを抑えるのが微分と覚える。", "kid": "比例は「今のズレの大きさ」、積分は「ズレがどれだけ長く残っているか」、微分は「ズレが急に変わっていないか」に注目して、それぞれ別の角度から入力を補正する。", "eg": "自転車のブレーキで例えると、比例は今どれだけ目標とずれているかを見て握る強さを決め、積分はずっとブレーキが甘くて微妙にずれ続けていることに気づいて握りを強め、微分は急に速度が変わりそうな勢いを感じ取って先に軽く握って備える、という3つの視点を組み合わせる。", "terms": [["比例動作(P)", "現在の偏差の大きさに比例して補正量を決める動作"], ["積分動作(I)", "偏差が時間的にどれだけ積み重なって残っているかに応じて補正量を決める動作。定常的な誤差を無くすのに効く"], ["微分動作(D)", "偏差の変化の速さに応じて補正量を決める動作。急な変化を早めに抑えるのに効く"]], "think": "比例動作だけでは、偏差が小さくなるほど補正量も小さくなるため、わずかな偏差が残ったまま補正が効かなくなる定常偏差が生じやすい。積分動作は、その残り続けている偏差を時間的に積み重ねて評価し、少しずつでも補正を積み増していくことで、定常偏差を無くす方向に働く。一方、比例や積分だけでは偏差が急激に変化する場面で補正が追いつかず、オーバーシュートや振動が大きくなりやすい。微分動作は偏差の変化の速さを見て、変化が急なときほど早めに強く補正をかけることで、行き過ぎや振動を抑える役割を持つ。この3つを組み合わせることで、定常偏差を無くしつつ、行き過ぎや振動も抑えた安定した制御が実現しやすくなる。", "opt": ["正解。比例は現在の偏差の大きさ、積分は偏差の積み重なり、微分は偏差の変化の速さに、それぞれ着目して補正量を決める。", "各動作が着目する対象が入れ替わっている。偏差の大きさに応じて補正するのは比例、変化の速さに応じて補正するのは微分である。", "3つの動作は着目する対象が異なり、同じ計算式ではない。役割が違うからこそ組み合わせる意味がある。", "PID制御が調整するのは制御対象への入力(操作量)であり、目標値の書き換えや測定間隔の変更、アクチュエーターの種類の切り替えを行うものではない。"]}'),
  ('ap-core-q192', '計測・制御に関する理論', '制御システムにおけるセンサーとアクチュエーターの役割分担に関する記述として、最も適切なものはどれか。', NULL::text, '["センサーは物理量を検出して電気信号に変換し、アクチュエーターは電気信号を受け取って物理的な動きに変換する。", "センサーは電気信号を物理的な動きに変換し、アクチュエーターは物理量を検出して電気信号に変換する。", "センサーとアクチュエーターはどちらも物理量を検出する役割を持ち、動きを生み出す部品は別に存在する。", "センサーとアクチュエーターはどちらも電気信号を物理的な動きに変換する役割を持ち、検出する部品は別に存在する。"]', 0, '[0]', 'single', '{"asked": "制御システムにおけるセンサーとアクチュエーターの役割分担について問うている。", "point": "物理量を電気信号に変換して読み取るのがセンサー、電気信号を物理的な動きに変換して働きかけるのがアクチュエーターと覚える。", "kid": "センサーは「測る係」、アクチュエーターは「動かす係」。", "eg": "エアコンでは温度センサーが今の室温を測って電気信号に変え、コンプレッサーやファン(アクチュエーター)がその指令を受けて実際に冷たい風を送り出す。", "terms": [["センサー", "温度・圧力・光などの物理量を検出し、電気信号に変換して出力する機器"], ["アクチュエーター", "制御器から受け取った電気信号を、モーターの回転や弁の開閉のような物理的な動きに変換する機器"]], "think": "制御システムは、制御対象の状態という物理量そのものを直接計算処理することはできない。そこでセンサーが物理量(温度・圧力・位置など)を検出し、制御器が扱える電気信号に変換して渡す。制御器はその信号と目標値を比較して補正量を計算するが、この補正量も電気信号のままでは制御対象を直接動かせない。そこでアクチュエーターが、その電気信号をモーターの回転や弁の開閉のような物理的な動きに変換し、実際に制御対象へ働きかける。つまりセンサーは物理量から電気信号への変換、アクチュエーターは電気信号から物理的な動きへの変換という、互いに逆向きの変換を担っている。", "opt": ["正解。センサーは物理量を検出して電気信号に変換する役割、アクチュエーターは電気信号を受けて物理的な動きに変換する役割を担う。", "センサーとアクチュエーターの役割が入れ替わっている。物理量を検出するのはセンサー、動きに変換するのはアクチュエーターである。", "物理量を検出する役割はセンサーが担っており、動きを生み出す役割は別の部品ではなくアクチュエーターである。", "動きに変換する役割はアクチュエーターが担っており、検出する役割は別の部品ではなくセンサーである。"]}')
) AS v(source_ref, category_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('ap-core-q193', 'コンパイラ理論とプログラミング言語論',
   'コンパイラの処理過程のうち、ソースプログラムの文字列を「予約語」「識別子」「数値」などの意味のある最小単位(トークン)に分割する処理はどれか。',
   NULL::text,
   '["字句解析","構文解析","意味解析","コード生成"]',
   0, '[0]', 'single',
   '{"asked":"コンパイラの処理過程のうち、文字列をトークンという最小単位に分割する処理はどれかを問うている。","point":"文字の並びを『単語』の単位に区切るだけの処理なら字句解析。文法として正しいかどうかまでは見ていない。","kid":"コンパイラは、プログラムを翻訳するときにいくつかの段階を順番に踏む。最初の段階が、文字の並びを意味のある単語(トークン)に区切る作業で、これが字句解析。","eg":"文章を読むとき、まずひとつづきの文字の並びを『これは名詞』『これは動詞』という単語の単位に区切る作業に似ている。文として正しいかはまだ見ていない。","terms":[["トークン","プログラムを構成する最小の意味単位。予約語・識別子・数値・記号など"],["予約語","if・whileのように、言語があらかじめ意味を決めている単語"],["識別子","変数名や関数名など、プログラマが自由に付ける名前"]],"think":"コンパイラは文字の並びをいきなり文法チェックにかけるわけではない。まず文字の並びを単語(トークン)の単位に区切っておかないと、次の構文解析で『この単語とこの単語がどう並んでいるか』を判断できないから。だから最初の段階として字句解析が必要になる。","vs":"構文解析と混同しやすいが、字句解析は『単語に区切る』段階、構文解析は『区切られた単語が文法通りに並んでいるか』を調べる段階で、担当する仕事の粒度が違う。","why_asked":"コンパイラの処理過程を段階ごとに正しく区別できているかを問う定番の出題。字句解析と構文解析の役割を逆に覚えていると誤答する。","opt":["正解。文字列を予約語・識別子・数値などのトークンという最小単位に分割する処理である。","構文解析は、区切られたトークンの並びが文法規則に沿っているかを検査し、プログラムの構造を組み立てる処理である。","意味解析は、型の矛盾や未宣言の変数の使用など、文法的には正しくても意味的に誤っている点を検出する処理である。","コード生成は、意味解析までを終えたプログラムから、実際にコンピュータが実行できる目的プログラムを作り出す処理である。"],"viz":"<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"170\" y=\"18\" text-anchor=\"middle\" font-size=\"11\" fill=\"#8892a4\">コンパイラの処理過程</text><rect x=\"10\" y=\"45\" width=\"56\" height=\"40\" rx=\"6\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"38\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#e8eaf0\">字句解析</text><text x=\"38\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">トークン化</text><line x1=\"66\" y1=\"65\" x2=\"96\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"96,65 90,61 90,69\" fill=\"#3b82f6\"/><rect x=\"98\" y=\"45\" width=\"56\" height=\"40\" rx=\"6\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"126\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#e8eaf0\">構文解析</text><text x=\"126\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">文法チェック</text><line x1=\"154\" y1=\"65\" x2=\"184\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"184,65 178,61 178,69\" fill=\"#3b82f6\"/><rect x=\"186\" y=\"45\" width=\"56\" height=\"40\" rx=\"6\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"214\" y=\"62\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#e8eaf0\">意味解析</text><text x=\"214\" y=\"76\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">型チェック等</text><line x1=\"242\" y1=\"65\" x2=\"272\" y2=\"65\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"272,65 266,61 266,69\" fill=\"#3b82f6\"/><rect x=\"274\" y=\"45\" width=\"56\" height=\"40\" rx=\"6\" fill=\"#20242f\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"302\" y=\"60\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">コード</text><text x=\"302\" y=\"72\" text-anchor=\"middle\" font-size=\"9\" fill=\"#e8eaf0\">生成</text><text x=\"170\" y=\"105\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8892a4\">ソースプログラム → … → 目的プログラム</text><text x=\"170\" y=\"120\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">(コード生成の段階で最適化も行われる)</text></svg>"}'),

  ('ap-core-q194', 'コンパイラ理論とプログラミング言語論',
   '字句解析で得られたトークンの並びが、あらかじめ定められた文法規則に従っているかを検査し、プログラムの構造(構文木)を組み立てる処理はどれか。',
   NULL::text,
   '["構文解析","字句解析","意味解析","コード生成"]',
   0, '[0]', 'single',
   '{"asked":"トークンの並びが文法規則に沿っているかを検査し、プログラムの構造を組み立てる処理はどれかを問うている。","point":"トークンの並び方が文法として正しいかを見るなら構文解析。個々のトークンの意味(型など)まではまだ見ていない。","kid":"字句解析で単語に区切ったあと、その単語たちが文法のルール通りに並んでいるかをチェックし、プログラムの組み立て構造を作るのが構文解析。","eg":"単語に区切ったあと、『主語のあとに動詞、そのあとに目的語』のように、単語の並び順が文法として成立しているかをチェックする作業に似ている。","terms":[["構文木","トークンの並びを、プログラムの構造がわかる木の形に組み立てたもの"],["文法規則","トークンをどの順番でどう並べればよいかを定めたルール"]],"think":"字句解析でトークンに区切っただけでは、それらが正しい順番で並んでいるかはまだわからない。たとえば記号のトークンが単独で出てきても、文法的に許される位置にあるかは別問題である。だから字句解析のあとに、並び順を文法規則と照らし合わせて検査する構文解析が必要になる。","vs":"意味解析と混同しやすいが、構文解析は『並び順が文法として正しいか』を見る段階で、変数の型が正しいかどうかといった意味の整合性はまだ見ていない。","why_asked":"字句解析・構文解析・意味解析の役割の違いを正しく区別できているかを問う。","opt":["正解。トークンの並びが文法規則に従っているかを検査し、プログラムの構造(構文木)を組み立てる処理である。","字句解析は、ソースプログラムの文字列を予約語・識別子・数値などのトークンという最小単位に分割する処理である。","意味解析は、型の矛盾や未宣言の変数の使用など、文法的には正しくても意味的に誤っている点を検出する処理である。","コード生成は、意味解析までを終えたプログラムから、実際にコンピュータが実行できる目的プログラムを作り出す処理である。"]}'),

  ('ap-core-q195', 'コンパイラ理論とプログラミング言語論',
   '構文的には正しく並んでいても、宣言されていない変数を使っていたり、型が矛盾する演算をしていたりする誤りを検出する処理はどれか。',
   NULL::text,
   '["意味解析","構文解析","字句解析","コード生成"]',
   0, '[0]', 'single',
   '{"asked":"文法的には正しくても意味的に誤りがある箇所を検出する処理はどれかを問うている。","point":"文法として並び方は正しいのに内容として矛盾している(型が合わない・宣言されていない等)誤りを見つけるなら意味解析。","kid":"構文解析で『並び方は正しい』と確認されたプログラムでも、実は宣言していない変数を使っていたり、数値のつもりの変数に文字を入れていたりすることがある。こうした『意味としての矛盾』を見つけるのが意味解析。","eg":"文法的には正しい文章でも、内容が矛盾している場合がある。『赤い四角い丸を描いた』は文法として成立していても、意味としてはおかしい。これと同じように、プログラムも並び方が正しいだけでは足りず、意味の矛盾がないかを別途チェックする必要がある。","terms":[["未宣言の変数","プログラム中で使う前に、その存在を宣言していない変数"],["型の矛盾","整数型の変数に文字列を代入するなど、扱う値の種類が一致しない状態"]],"think":"構文解析までは『並び方が文法として成立しているか』しか見ていない。並び方が正しくても、使われている変数が実際に宣言されているか、演算の両側の型が噛み合っているかは、単語の並び方だけでは判断できず、それぞれの単語(変数や式)が実際に何を意味するかまで踏み込んで確認する必要がある。だから構文解析の次に、意味を確認する意味解析という段階が置かれている。","vs":"構文解析と混同しやすいが、構文解析は『並び方』、意味解析は『並び方は正しい前提で、内容が矛盾していないか』を見る点で役割が異なる。","why_asked":"『構文的に正しくても意味的に誤りうる』という考え方そのものを理解しているかを問う、この分野の中心的な出題。","opt":["正解。構文的には正しく並んでいても、未宣言の変数の使用や型の矛盾など、意味的な誤りを検出する処理である。","構文解析は、トークンの並びが文法規則に従っているかを検査し、プログラムの構造(構文木)を組み立てる処理である。","字句解析は、ソースプログラムの文字列を予約語・識別子・数値などのトークンという最小単位に分割する処理である。","コード生成は、意味解析までを終えたプログラムから、実際にコンピュータが実行できる目的プログラムを作り出す処理である。"]}'),

  ('ap-core-q196', 'コンパイラ理論とプログラミング言語論',
   '意味解析までを終えたプログラムをもとに、実際にコンピュータが実行できる目的プログラムを作り出す処理はどれか。この処理では、無駄な計算を取り除くなどして実行効率を高める工夫も合わせて行われることが多い。',
   NULL::text,
   '["コード生成","トークン分割","構文解析","意味解析"]',
   0, '[0]', 'single',
   '{"asked":"意味解析を終えたプログラムから、実行可能な目的プログラムを作り出す処理はどれかを問うている。","point":"字句解析・構文解析・意味解析をすべて終えたあと、最後に実行可能な形へ落とし込む処理ならコード生成。","kid":"字句解析・構文解析・意味解析で『正しいプログラムだ』と確認されたあと、最後にコンピュータが実際に実行できる機械語などの目的プログラムを組み立てるのがコード生成。このとき、無駄な処理を省くなどの最適化も一緒に行われることが多い。","eg":"翻訳者が原文の文法と意味の確認をすべて終えたあとに、ようやく訳文を清書して仕上げるようなもの。清書の際に、読みやすいよう無駄な言い回しを整理する(最適化する)こともある。","terms":[["目的プログラム","翻訳の結果として作られる、コンピュータが実行できる形式のプログラム"],["最適化","処理結果を変えずに、実行時間やメモリの使用量を減らす工夫"]],"think":"字句解析・構文解析・意味解析は、いずれもソースプログラムが正しいかを段階的に確認する処理であり、それ自体は実行できる形を作らない。すべての確認を終えて初めて、確認済みの内容をもとに実際に動く目的プログラムへ変換できる。だから処理過程の最後にコード生成が置かれる。","vs":"意味解析と混同しやすいが、意味解析は『誤りがないかを確認する』段階、コード生成は『確認が済んだ内容を実行可能な形に変換する』段階で、確認と変換という役割の違いがある。","why_asked":"処理過程の最後の段階が何を指すかを問う。最適化を独立した別工程だと思い込み、コード生成と切り離して考えてしまう誤解を確認する狙いもある。","opt":["正解。意味解析までを終えたプログラムから、実行可能な目的プログラムを作り出す処理であり、無駄な計算を取り除く最適化も合わせて行われることが多い。","文字列をトークンへ分割する処理(字句解析)であり、コンパイルの最初の段階で行われる。目的プログラムを作り出す処理ではない。","構文解析は、トークンの並びが文法規則に従っているかを検査し、プログラムの構造(構文木)を組み立てる処理である。","意味解析は、型の矛盾や未宣言の変数の使用など、文法的には正しくても意味的に誤っている点を検出する処理である。"]}'),

  ('ap-core-q197', 'コンパイラ理論とプログラミング言語論',
   'プログラムの実行方式に関する記述のうち、コンパイラ方式の説明として適切なものはどれか。',
   NULL::text,
   '["ソースプログラム全体を先に目的プログラムへ翻訳し、翻訳を終えてから実行する方式である。","ソースプログラムを先頭から1文ずつ、その場で翻訳しながら逐次実行していく方式のことである。","複数の目的プログラムやライブラリを1つの実行可能ファイルへまとめて結合する、リンカが行う処理のことである。","ソースプログラムの誤りを検出して報告するためだけに用いられ、目的プログラムを一切生成しない方式である。"]',
   0, '[0]', 'single',
   '{"asked":"プログラムの実行方式のうち、コンパイラ方式の特徴を問うている。","point":"『全部訳してから実行する』ならコンパイラ方式、『訳しながらその場で実行する』ならインタプリタ方式。","kid":"コンパイラ方式は、ソースプログラム全体を先にすべて目的プログラムへ翻訳しておき、翻訳が終わったあとで、その目的プログラムを実行する方式。","eg":"コンパイラは、本を1冊まるごと先に翻訳してから読者に渡す翻訳者のようなもの。渡された読者は、すでに翻訳済みの本を読むだけでよい。","terms":[["目的プログラム","翻訳の結果として作られる、コンピュータが実行できる形式のプログラム"],["一括翻訳","ソースプログラム全体をまとめて先に翻訳しておくこと"]],"think":"コンパイラ方式では、実行を始める前にソースプログラム全体の翻訳をすべて終えておく。だから実行時にはすでに翻訳済みの目的プログラムが手元にあり、翻訳作業と実行作業が分かれた2つの段階になる。","vs":"インタプリタ方式と混同しやすいが、インタプリタ方式は翻訳と実行を1文ずつ交互に繰り返す方式で、翻訳をすべて終えてから実行するコンパイラ方式とは段階の分け方が異なる。","why_asked":"コンパイラとインタプリタという2つの実行方式の違いを正しく理解しているかを問う基本問題。","opt":["正解。ソースプログラム全体を先に目的プログラムへ翻訳し、翻訳を終えてから実行する方式である。","この説明はインタプリタ方式のものである。ソースプログラムを1文ずつ翻訳しながら、その場で実行していく方式である。","この説明はリンカが行う結合の処理であり、コンパイラ方式そのものの説明ではない。","この説明は誤り検査だけを行う仕組みの説明であり、コンパイラ方式は目的プログラムを生成する点でこれとは異なる。"],"viz":"<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><text x=\"10\" y=\"18\" font-size=\"10\" fill=\"#60a5fa\">コンパイラ方式</text><rect x=\"10\" y=\"26\" width=\"80\" height=\"30\" rx=\"5\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"50\" y=\"45\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#e8eaf0\">ソース全体</text><line x1=\"90\" y1=\"41\" x2=\"112\" y2=\"41\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"112,41 106,37 106,45\" fill=\"#3b82f6\"/><rect x=\"114\" y=\"26\" width=\"88\" height=\"30\" rx=\"5\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"158\" y=\"45\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#e8eaf0\">一括で翻訳</text><line x1=\"202\" y1=\"41\" x2=\"224\" y2=\"41\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><polygon points=\"224,41 218,37 218,45\" fill=\"#3b82f6\"/><rect x=\"226\" y=\"26\" width=\"104\" height=\"30\" rx=\"5\" fill=\"#20242f\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"278\" y=\"45\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#e8eaf0\">目的プログラムを実行</text><text x=\"10\" y=\"85\" font-size=\"10\" fill=\"#c9a04a\">インタプリタ方式</text><rect x=\"10\" y=\"93\" width=\"90\" height=\"30\" rx=\"5\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"55\" y=\"112\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#e8eaf0\">ソース(1文)</text><line x1=\"100\" y1=\"108\" x2=\"122\" y2=\"108\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><polygon points=\"122,108 116,104 116,112\" fill=\"#c9a04a\"/><rect x=\"124\" y=\"93\" width=\"140\" height=\"30\" rx=\"5\" fill=\"#20242f\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"194\" y=\"112\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#e8eaf0\">翻訳しながら実行</text><text x=\"194\" y=\"135\" text-anchor=\"middle\" font-size=\"8\" fill=\"#8892a4\">これを1文ごとに繰り返す</text></svg>"}'),

  ('ap-core-q198', 'コンパイラ理論とプログラミング言語論',
   'コンパイラ方式とインタプリタ方式の一般的な特徴の違いに関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["コンパイラ方式は事前に翻訳を済ませておくため実行時の速度で有利になりやすく、インタプリタ方式は修正して即座に動作を確認するのに向く。","コンパイラ方式は実行のたびに一からソースプログラムの翻訳をやり直すため低速になりやすく、インタプリタ方式は事前に翻訳を済ませておくため高速になりやすい。","コンパイラ方式は目的プログラムを生成しないため単体では配布ができず、インタプリタ方式は目的プログラムを生成するため単体で配布できる。","コンパイラ方式とインタプリタ方式では、翻訳の段階が異なるだけで、生成される目的プログラムの中身は完全に同じであり、違いは存在しない。"]',
   0, '[0]', 'single',
   '{"asked":"コンパイラ方式とインタプリタ方式の一般的な特徴の違いを問うている。","point":"『実行前にすべて翻訳を済ませておくか』の違いが、そのまま『実行速度』と『修正のしやすさ』のどちらを優先しやすいかに直結する。","kid":"コンパイラ方式は先に翻訳を済ませてしまうので、実行時は翻訳の手間がかからず速く動きやすい。インタプリタ方式は1文ずつ翻訳しながら実行するので、コードを直してすぐ試すといった作業がしやすい。","eg":"コンパイラは、旅行に出る前にガイドブックをまるごと翻訳しておく方式。出発後は翻訳の手間がないので身軽に動ける。インタプリタは、その場で通訳を連れて歩く方式。翻訳の手間は毎回かかるが、予定を急に変えてもすぐ対応できる。","terms":[["実行時の速度","プログラムを実際に動かしているときにかかる処理時間"],["即座に動作を確認","コードを少し直しては、すぐに結果を確かめる作業のしやすさ"]],"think":"コンパイラ方式は実行前に翻訳を終えているので、実行中は目的プログラムを読んで動かすだけで済み、翻訳にかかる手間が実行時間に上乗せされない。一方インタプリタ方式は、実行のたびに1文ずつ翻訳の手間がかかるが、その代わりソースプログラムを直したらすぐその場で試せる。どちらの方式を選ぶかで、実行速度を優先するか、修正のしやすさを優先するかのトレードオフが生まれる。","vs":"『どちらが優れているか』という単純な優劣ではなく、実行速度を優先するか、修正して即座に試す手軽さを優先するかというトレードオフである点を混同しないこと。","why_asked":"コンパイラ方式とインタプリタ方式それぞれの利点を正しい組み合わせで理解しているか、逆に取り違えていないかを問う。","opt":["正解。コンパイラ方式は事前に翻訳を済ませておくため実行時の速度で有利になりやすく、インタプリタ方式は修正して即座に動作を確認するのに向く。","実行時の速度に関する説明が逆である。事前に翻訳を済ませておくコンパイラ方式のほうが、実行時に翻訳の手間がかからない分、速度で有利になりやすい。","目的プログラムの生成に関する説明が逆である。コンパイラ方式こそ目的プログラムを生成して配布できる点が特徴であり、インタプリタ方式はソースプログラムを都度翻訳しながら実行する。","両方式は翻訳と実行の段階の分け方が異なり、実行速度や修正のしやすさに違いが生じる。目的プログラムの中身や実行方式が同じというわけではない。"]}'),

  ('ap-core-q199', 'コンパイラ理論とプログラミング言語論',
   'プログラミング言語における「静的型付け」の説明として適切なものはどれか。',
   NULL::text,
   '["変数の型がコンパイル時(プログラムを翻訳する段階)に決定され、型が矛盾する演算はその時点で誤りとして検出される。","変数の型が実行時(プログラムを動かしている最中)に、代入された値に応じてその都度決定され、実行のたびに異なる型を持つこともある。","変数に一度型を割り当てると、そのプログラムの実行が終わるまで、その変数へは二度と別の値を代入できなくなってしまう。","変数の型を宣言するための構文そのものが、その言語の仕様には一切存在しない。"]',
   0, '[0]', 'single',
   '{"asked":"『静的型付け』が何を意味するかを問うている。","point":"型がいつ決まるかがカギ。コンパイル時に決まるなら静的型付け、実行時に決まるなら動的型付け。","kid":"静的型付けの言語では、プログラムを実行する前の翻訳の段階で、それぞれの変数がどんな型(整数・文字列など)かがすでに決まっている。だから型が合わない演算があれば、実行する前に誤りとして見つけられる。","eg":"静的型付けは、旅行の荷物を出発前にすべてリストで確認しておくようなもの。『このバッグには衣類しか入れない』と最初に決めておけば、間違って別の物を詰めようとした時点で気づける。","terms":[["コンパイル時","プログラムを実行する前に、ソースプログラムを目的プログラムへ翻訳している段階"],["型","整数・小数・文字列など、変数が扱う値の種類"]],"think":"静的型付けの言語では、コンパイラが翻訳の段階(意味解析)で、それぞれの変数がどの型かをあらかじめ確定させる。型が確定しているからこそ、その場で『この演算はこの型同士では成立しない』と判定でき、実行する前に誤りとして検出できる。型がいつ決まるかという一点が、静的型付けと動的型付けを分ける境界線になる。","vs":"動的型付けと混同しやすいが、動的型付けは型が実行時に決まり、同じ変数に別の型の値を入れ直すこともできる点が異なる。","why_asked":"静的型付けを『型を宣言する言語』程度の理解で止めず、『型がいつ決まるか』という本質を理解しているかを問う。","opt":["正解。変数の型がコンパイル時に決定され、型が矛盾する演算はその時点で誤りとして検出される。","この説明は動的型付けのものである。変数の型は実行時に代入された値によってその都度決定され、変わりうる。","型付けの方式は、型がいつ決まるかに関する分類であり、一度代入した値を変更できるかどうかという性質とは別の話である。","静的型付けの言語であっても、変数の型を宣言する構文は存在する。型が実行前に決まる点が静的型付けの特徴である。"]}'),

  ('ap-core-q200', 'コンパイラ理論とプログラミング言語論',
   '動的型付け言語の特徴として適切なものはどれか。',
   NULL::text,
   '["同じ変数に対して実行の途中で異なる型の値を代入でき、型が矛盾する演算は実行時にその演算が行われて初めて検出される。","変数の型はコンパイル時にあらかじめ確定しており、プログラムの実行中に型が変わることは一切なく、常に同じ型のままである。","すべての変数の型を、プログラムの先頭でまとめて宣言しておかなければ、コンパイルすら通らない。","型の検査そのものを一切行わないため、どのような演算をしても誤りとして検出されることは決してない。"]',
   0, '[0]', 'single',
   '{"asked":"動的型付け言語の特徴を問うている。","point":"型がいつ決まるかがカギ。実行時に、代入された値によってその都度決まるなら動的型付け。","kid":"動的型付けの言語では、変数の型はプログラムを実行しながら、実際に代入された値によってその都度決まる。だから同じ変数に、あるときは数値、別のときは文字列を入れ直すこともできる。","eg":"動的型付けは、同じ箱にそのときどきで違う種類の物を入れ替えて使うようなもの。箱自体には『何を入れる箱か』という決まりがなく、入れてみて初めて中身がわかる。","terms":[["実行時","プログラムを実際に動かしている最中の段階"],["型の矛盾","演算の両側で扱う値の種類が噛み合わない状態"]],"think":"動的型付けの言語では、変数そのものに型を固定しておらず、値を代入した瞬間にその値の型がその変数の型として扱われる。次に別の型の値を代入すれば、変数の型もそちらに変わる。型を実行前に固定していない以上、型が矛盾する演算があるかどうかも、実際にその演算が実行されるまでは判定できない。だから動的型付けでは、型の誤りは実行時にその箇所を通って初めて発覚する。","vs":"静的型付けと混同しやすいが、静的型付けはコンパイル時に型が確定し実行前に誤りを検出できる点で、実行時まで型の誤りがわからない動的型付けと対照的である。","why_asked":"静的型付けと対にして、『型がいつ決まるか』という基準で正しく区別できているかを問う。","opt":["正解。同じ変数に対して実行の途中で異なる型の値を代入でき、型が矛盾する演算は実行時にその演算が行われて初めて検出される。","この説明は静的型付けのものである。変数の型はコンパイル時にあらかじめ確定し、実行中に型が変わることはない。","動的型付け言語の多くは、変数の型を事前に宣言しなくても値を代入できる点が特徴であり、先頭でまとめて宣言する必要があるという説明は当てはまらない。","動的型付けでも型の検査自体は行われる。ただしその検査のタイミングが実行時になる点が、コンパイル時に検査する静的型付けとの違いである。"]}'),

  ('ap-core-q201', 'コンパイラ理論とプログラミング言語論',
   '静的型付け言語の利点に関する記述として適切なものはどれか。',
   NULL::text,
   '["型の矛盾をコンパイル時に検出できるため、実行してみて初めて型の誤りが発覚するという事態を減らせる。","型を宣言する手間が一切かからないため、動的型付け言語よりも常に短いコードで簡潔に書けるようになる。","実行時に型を判定する処理が発生しないため、動的型付け言語よりも必ず少ないメモリしか使わない。","どのような値を代入しても自動的に型を変換してくれるため、型に関するエラーは一切発生しなくなる。"]',
   0, '[0]', 'single',
   '{"asked":"静的型付け言語であることの利点を問うている。","point":"『実行する前に誤りを見つけられる』ことが静的型付けの最大の利点。","kid":"静的型付け言語は、型の矛盾をプログラムの実行前(コンパイル時)に見つけられる。だから、実際にユーザーが使っている最中に型の誤りで止まってしまう、という事態を減らせる。","eg":"出発前の持ち物チェックリストのようなもの。旅行先で『あれを忘れた』と気づくより、出発前のチェックで気づくほうが被害が少ない。静的型付けは、この『出発前のチェック』を型についてコンパイラが代わりにやってくれるようなもの。","terms":[["実行前に検出","プログラムを動かす前の翻訳の段階で誤りが見つかること"],["型の矛盾","演算の両側で扱う値の種類が噛み合わない状態"]],"think":"型がコンパイル時に確定しているということは、コンパイラがソースプログラム全体を翻訳する段階で、それぞれの演算の両側の型を照合できるということでもある。型が矛盾する箇所があれば、その場で誤りとして報告できる。もし型が実行時にしか決まらないなら、その演算が実際に実行されるまで矛盾に気づけず、ユーザーが使っている最中に初めて誤りが表面化してしまう。だから型を早い段階(コンパイル時)で確定させておくことが、誤りの早期発見につながる。","vs":"動的型付けと混同しやすいが、動的型付けは型の宣言が少なく書きやすい面がある一方、型の誤りは実行時にしか発覚しない。静的型付けの利点は『書きやすさ』ではなく『誤りを早く見つけられること』にある。","why_asked":"静的型付けの利点を、宣言の手間やメモリ量といった副次的な話とすり替えず、『誤りの早期発見』という本質で理解しているかを問う。","opt":["正解。型の矛盾をコンパイル時に検出できるため、実行してみて初めて型の誤りが発覚するという事態を減らせる。","静的型付け言語では、多くの場合むしろ変数の型を宣言する記述が必要になり、動的型付け言語より宣言の手間が増える傾向がある。短く書けるとは限らない。","実行時に型を判定する処理が省ける傾向はあるが、メモリの使用量は型の宣言方法だけでなく、扱うデータの構造など他の要因にも左右されるため、必ず少なくなるとは言えない。","静的型付けであっても、型が矛盾する演算があればコンパイル時に誤りとして検出される。自動的に型を変換してエラーを無くす仕組みとは異なる。"]}'),

  ('ap-core-q202', 'コンパイラ理論とプログラミング言語論',
   'プログラミング言語における「ローカル変数」の説明として適切なものはどれか。',
   NULL::text,
   '["関数やブロックなど、限られた範囲内で宣言され、その範囲の外からは参照できない変数である。","プログラム全体のどこからでも参照でき、値を変更するとプログラム全体に影響が及ぶ変数である。","一度宣言すると、プログラムの実行が終わるまで値を変更できない変数である。","関数の呼び出しが終わっても値を保持し続け、次に呼び出されたときも前回の値を引き継ぐ変数である。"]',
   0, '[0]', 'single',
   '{"asked":"『ローカル変数』が何を指すかを問うている。","point":"宣言された範囲(スコープ)の外から見えないなら、それがローカル変数。","kid":"ローカル変数は、関数やブロックといった限られた範囲の中だけで使える変数。その範囲の外からは、名前を呼んでも存在しないものとして扱われる。","eg":"ローカル変数は、会議室の中だけで使うホワイトボードのようなもの。会議室(関数)の中でだけ書いたり消したりでき、会議室の外にいる人からはそのホワイトボードの中身は見えないし、触れない。","terms":[["スコープ","変数が有効な(参照できる)範囲"],["グローバル変数","プログラム全体のどこからでも参照できる変数"]],"think":"ローカル変数は、宣言された関数やブロックが実行されている間だけ存在し、その範囲を抜けると参照できなくなる。範囲の外から見えないからこそ、『ローカル(局所的)』変数と呼ばれる。","vs":"グローバル変数と混同しやすいが、グローバル変数はプログラム全体のどこからでも参照できる点で、範囲が限定されるローカル変数と対照的である。また、値を変更できないという性質は定数の説明であり、ローカル変数とは別の概念である。","why_asked":"スコープという考え方の基本単位である『ローカル変数』を、グローバル変数や定数と正しく区別できているかを問う。","opt":["正解。関数やブロックなど、限られた範囲内で宣言され、その範囲の外からは参照できない変数である。","この説明はグローバル変数のものである。プログラム全体のどこからでも参照でき、値を変更するとプログラム全体に影響が及ぶ。","この説明は定数の性質に近い。ローカル変数は宣言後に値を変更できないわけではなく、有効な範囲が限定されている点が特徴である。","関数の呼び出しが終わっても値を保持し続ける変数は、通常のローカル変数とは異なる特別な性質を持つ変数であり、一般的なローカル変数の説明としては適切ではない。"],"viz":"<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\"><rect x=\"8\" y=\"15\" width=\"324\" height=\"125\" rx=\"8\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"20\" y=\"30\" font-size=\"9.5\" fill=\"#60a5fa\">グローバルスコープ(プログラム全体)</text><text x=\"20\" y=\"48\" font-size=\"8.5\" fill=\"#e8eaf0\">変数g</text><rect x=\"22\" y=\"58\" width=\"130\" height=\"68\" rx=\"6\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"87\" y=\"72\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8892a4\">関数Aのスコープ</text><text x=\"87\" y=\"98\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#e8eaf0\">変数x</text><rect x=\"186\" y=\"58\" width=\"130\" height=\"68\" rx=\"6\" fill=\"#20242f\" stroke=\"#2a2f3f\"/><text x=\"251\" y=\"72\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#8892a4\">関数Bのスコープ</text><text x=\"251\" y=\"98\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#e8eaf0\">変数y</text></svg>"}'),

  ('ap-core-q203', 'コンパイラ理論とプログラミング言語論',
   'プログラミング言語がローカル変数とグローバル変数という考え方でスコープ(有効範囲)を分けている目的として、最も適切なものはどれか。',
   NULL::text,
   '["変数の有効範囲を限定し、離れた場所にある同名の変数同士が影響し合う事故を防ぎ、部品を独立させるため。","変数の数そのものをできるだけ減らすことによって、プログラム全体で使用するメモリの総量を必ず削減するため。","プログラムの実行速度を少しでも高めるために、変数の型変換にかかる処理時間を短縮するため。","すべての変数を同じ名前でまとめて統一して管理できるようにし、命名規則そのものを単純化するため。"]',
   0, '[0]', 'single',
   '{"asked":"スコープという考え方を導入する目的を問うている。","point":"『同じ名前の変数が別の場所に影響しないようにする』ことがスコープを分ける最大の目的。","kid":"スコープを分けておくと、ある関数の中で使っている変数の名前が、別の関数の中で使っている同じ名前の変数とぶつかって、お互いに書き換え合ってしまうという事故を防げる。","eg":"会議室ごとにホワイトボードを分けておくようなもの。すべての会議室が1枚の共有ホワイトボードしか使えないと、ある会議室で書いた内容を別の会議室の人が誤って消してしまうかもしれない。会議室ごとにホワイトボードを分けておけば、そうした事故が起きない。","terms":[["スコープ","変数が有効な(参照できる)範囲"],["名前の衝突","異なる場所で使われている同名の変数が、意図せず同じものとして扱われてしまうこと"]],"think":"もしすべての変数がプログラム全体で共有される(グローバルである)なら、ある関数の中でうっかり付けた変数名が、別の関数がすでに使っている変数名と同じだった場合、お互いに気づかないまま値を書き換え合ってしまう。プログラムが大きくなるほど、変数の数も増え、この名前の衝突が起きる可能性も高まる。スコープを分けて変数を局所化しておけば、それぞれの関数は自分のスコープの中だけを気にすればよく、他の部分の変数名を気にせずに書ける。だから、部品(関数)同士を独立させて安全に組み合わせるために、スコープという考え方が必要になる。","vs":"メモリ削減や実行速度の向上と混同しやすいが、スコープを分ける主な目的は『変数同士の意図しない衝突を防ぐこと』であり、メモリ量や実行速度への影響は副次的なものにすぎない。","why_asked":"スコープという仕組みが『なぜ』必要とされているのかという、丸暗記では答えられない設計思想の理解を問う。","opt":["正解。変数の有効範囲を限定し、離れた場所にある同名の変数同士が意図せず影響し合う事故を防ぎ、プログラムの部品を独立させやすくするため。","スコープを分けても変数の総数そのものが減るわけではなく、メモリ使用量の削減を主目的とした仕組みではない。","スコープの分け方は変数が参照できる範囲を定めるものであり、型変換にかかる処理時間を短縮するための仕組みではない。","スコープを分けることで、同じ名前を異なる範囲で使い分けられるようになる。すべての変数を同じ名前に統一するための仕組みではない。"]}'),

  ('ap-core-q204', 'コンパイラ理論とプログラミング言語論',
   '「構文的には正しいが、意味的には誤っている」プログラムの例として最も適切なものはどれか。',
   NULL::text,
   '["文法規則には従って正しく書かれているが、宣言されていない変数を参照するなど、内容として整合性がとれていないプログラム。","括弧の対応が取れていなかったり、文の終わりを示す記号が抜けていたりして、文法規則そのものに違反しているようなプログラム。","使用しているキーワードのつづりが誤っていて、その言語の予約語として認識されない字句が含まれているプログラム。","プログラムの実行時間が想定よりも長くかかり、規定の時間内に処理が終わらないという性能上のプログラム。"]',
   0, '[0]', 'single',
   '{"asked":"『構文的には正しいが意味的には誤っている』とはどういう状態かを、具体例で問うている。","point":"並び方(文法)は合っているのに、内容(意味)が矛盾しているケースが『構文的に正しいが意味的に誤り』。","kid":"プログラムの誤りには段階がある。文字の並びが単語としておかしい誤り、単語の並び方が文法としておかしい誤り、そして並び方は正しいのに内容が矛盾している誤り。最後のものが『意味的な誤り』にあたる。","eg":"『4月に雪が2メートル積もったので、真夏日になった』という文は、日本語の文法としては正しく成立しているが、内容としては矛盾している。プログラムでも同じように、文法上は正しく書けていても、宣言していない変数を使うなど内容が矛盾していることがある。","terms":[["構文エラー","文法規則そのものに違反している誤り。字句解析や構文解析の段階で見つかる"],["意味エラー","文法的には正しいが、型の矛盾や未宣言の変数の使用など、内容が矛盾している誤り"]],"think":"誤りにはどの段階で見つかるかという順番がある。文字の並びが単語としてすら成立していなければ字句解析の段階で見つかる誤りになり、単語は成立していても並び方が文法に反していれば構文解析の段階で見つかる誤りになる。ここまでをすべてクリアしていても、宣言されていない変数を使っていたり型が矛盾していたりすれば、それは並び方の問題ではなく内容の問題であり、意味解析の段階で初めて見つかる誤りになる。この『どの段階で見つかるか』の違いが、構文的な誤りと意味的な誤りを分ける境界線になる。","vs":"文法違反(構文エラー)やつづりの誤り(字句エラー)と混同しやすいが、これらは並び方や単語そのものの誤りであり、並び方は正しいのに内容が矛盾している意味的な誤りとは見つかる段階が異なる。","why_asked":"『誤り』を一括りにせず、字句・構文・意味という段階ごとに正しく分類できているかを問う、この分野のまとめにあたる出題。","opt":["正解。文法規則には従って正しく書かれているが、宣言されていない変数を参照するなど、内容として整合性がとれていないプログラムであり、これが意味的な誤りにあたる。","括弧の対応や文の終わりの記号の欠落は、文法規則そのものへの違反であり、構文解析の段階で見つかる構文エラーにあたる。","キーワードのつづり誤りは、文字の並びが正しいトークンとして認識できない誤りであり、字句解析の段階で見つかる字句エラーにあたる。","実行時間が長くかかることは、性能上の問題であり、構文や意味が正しいかどうかとは別の観点である。"]}')

) AS v(source_ref, category_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('ap-core-q205', 'システム企画',
   '情報システムの企画プロセスにおける「システム化構想」の説明として、最も適切なものはどれか。',
   NULL::text,
   '["経営上の課題やニーズを分析し、それを解決する情報システム化の全体的な方向性や対象業務の範囲を明らかにする、企画プロセスの最初の段階である。","個々のシステムの内部設計や画面・帳票のレイアウトを、要件定義の内容に基づいて具体的に決定していく段階である。","開発体制やスケジュール、投資対効果の見積もりなど、システム化を実行するために必要となる事項を、より具体的な計画としてまとめて確定する段階である。","開発が完了したシステムを本番環境へ移行し、利用者への説明会や運用マニュアルの整備を行い、稼働を開始する段階である。"]',
   0, '[0]', 'single',
   '{"asked":"企画プロセスの最初の段階である「システム化構想」が何を指すかを問う設問。","point":"『まだ大枠・方向性を決めるだけ』の段階ならシステム化構想。体制やスケジュールまで具体化するのはその次の段階(システム化基本方針)。","kid":"システム化構想は、会社が抱えている課題を見て『情報システムでどう解決していくか』の大きな方向性だけを決める最初の話し合い。まだ細かい計画表は作らない。","eg":"家を建てる前の『どんな暮らしがしたいか』を家族で話し合う段階に近い。部屋の広さや工期(スケジュール)を決めるのはもっと後。","terms":[["企画プロセス","情報システムを作る一連の流れのうち、最初に『何を作るか』を決める段階"],["システム化基本方針","システム化構想を受けて、開発体制・スケジュール・投資対効果などを具体化した方針"]],"think":"なぜ『構想』と『具体化』を分けて考える必要があるのかがカギ。いきなり体制やスケジュールを決めてしまうと、そもそも解決すべき経営課題が何なのかがあいまいなまま話が進み、後になって何のためのシステムだったのかがずれてしまう。そこでまず経営課題を分析し、システム化の大きな方向性(対象業務、期待する効果の方向)を固める段階を独立させる。それがシステム化構想であり、体制やスケジュールといった実行計画は、方向性が固まった後のシステム化基本方針で決める。","why_asked":"システム化構想とシステム化基本方針を混同させる設問は頻出。両者の役割の違い(方向性を決めるか、実行計画を決めるか)を区別できるかが問われる。","vs":"投資対効果やスケジュールなど『実行するための具体的な計画』を確定するのはシステム化基本方針の役割。システム化構想はそれより前の、方向性を定める段階。","opt":["正解。経営課題の分析から情報システム化の方向性・対象業務の範囲を明らかにする、企画プロセスの最初の段階である。","内部設計や画面・帳票レイアウトの決定はシステム設計工程の作業であり、企画プロセスより後の段階である。","開発体制やスケジュール、投資対効果の見積もりを確定するのはシステム化基本方針の役割であり、システム化構想より後の段階である。","本番移行や利用者説明会、運用マニュアル整備は、開発が完了した後の導入・運用段階の作業である。"]}'),

  ('ap-core-q206', 'システム企画',
   'システム化構想を受けて策定される「システム化基本方針」に、一般に含まれる内容として、最も適切なものはどれか。',
   NULL::text,
   '["対象業務の範囲、開発体制、概算のスケジュールや投資対効果など、システム化を進めるための具体的な方針","プログラムの内部構造やモジュール分割の設計など、開発者向けの詳細な技術仕様情報","全社的な経営戦略そのものをあらためて新たに策定し直し、今後数年間にわたる中期経営計画を新たに定めるための内容","システム運用開始後に発生した障害の件数や対応時間を集計した、運用実績の報告内容"]',
   0, '[0]', 'single',
   '{"asked":"システム化構想の後に作られる「システム化基本方針」の中身を問う設問。","point":"『対象業務・体制・スケジュール・投資対効果の見積もりを、実行に移せる形まで具体化した方針』ならシステム化基本方針。","kid":"システム化構想で決めた大きな方向性を受けて、誰が、いつまでに、どれくらいのお金をかけて進めるかを、もう少し具体的な方針としてまとめたもの。","eg":"家を建てる例で言うと、『どんな暮らしがしたいか』(構想)の次に、『予算はいくらまで、工期は何か月、どの工務店に頼むか』を方針として固める段階。","terms":[["投資対効果","かけた費用に対して、どれだけの効果(コスト削減や売上増加など)が見込めるかという見積もり"]],"think":"なぜ構想の次に基本方針という段階が要るのかがカギ。システム化構想はまだ方向性しか決めていないため、このままでは誰がいくらの予算でいつまでに進めるのかが分からず、実際の開発に着手できない。そこでシステム化構想の内容を、対象業務の範囲・開発体制・概算スケジュール・投資対効果の見積もりという、実行に移せる具体性まで落とし込む段階が必要になる。それがシステム化基本方針であり、この後に個別の開発計画や要件定義へと進んでいく。","why_asked":"システム化基本方針の内容を、経営戦略の策定や詳細設計、運用実績報告など隣接工程の内容と混同させる出題が多い。","vs":"内部構造やモジュール分割は開発工程の詳細設計の話であり、システム化基本方針の段階ではまだそこまで具体化しない。","opt":["正解。対象業務の範囲、開発体制、概算のスケジュールや投資対効果など、システム化を進めるための具体的な方針を定める。","プログラムの内部構造やモジュール分割は、開発工程の詳細設計で扱う内容であり、システム化基本方針の段階ではまだ扱わない。","全社の中期経営計画を新たに策定するのは経営戦略のレベルの話であり、個別のシステム化を具体化するシステム化基本方針とは階層が異なる。","運用実績の集計・報告は、システムが稼働を始めた後の運用段階で行う作業である。"]}'),

  ('ap-core-q207', 'システム企画',
   E'次のア〜エは、情報システムを企画してから設計に着手するまでの作業である。一般的な順序として、最も適切なものはどれか。\nア　個別システムの要件定義\nイ　システム化構想の立案\nウ　システム化基本方針の策定\nエ　システムの設計',
   NULL::text,
   '["イ→ウ→ア→エ","ア→イ→ウ→エ","ウ→イ→エ→ア","エ→ア→イ→ウ"]',
   0, '[0]', 'single',
   '{"asked":"システム化構想の立案からシステム設計に着手するまでの、企画プロセスの一般的な順序を問う設問。","point":"『まず方向性(構想)、次に実行方針(基本方針)、それから個別システムの要件を固める(要件定義)、最後に中身を作る(設計)』の順。方向性が定まる前に個別の要件や設計には進まない。","kid":"会社の課題を見て大きな方向性を決めてから(システム化構想)、それを具体的な方針にし(システム化基本方針)、個々のシステムで何が必要かを決め(要件定義)、最後に中身を作る(設計)、という順番。","eg":"家づくりで言うと、『どんな暮らしがしたいか』(構想)の次に『予算・工期の方針』(基本方針)を決め、『各部屋に何が必要か』(要件定義)を固めてから『間取り図を引く』(設計)、という順番と同じ。いきなり間取り図から始めることはない。","terms":[["要件定義","個別のシステムに何が必要かを明確にする工程"],["システム設計","要件定義で固めた内容をもとに、システムの内部構造や画面などを具体的に決める工程"]],"think":"なぜこの順序でないと進められないのかがカギ。方向性(システム化構想)が定まらないうちに個別システムの要件を決めてしまうと、そもそも何のために作るシステムなのかが揺らぎ、後で経営課題とずれた要件になってしまう。また、要件が固まらないうちに設計に進むと、何を作るべきかが曖昧なまま内部構造を決めることになり、手戻りが起きる。だから、方向性を決め、それを実行方針に落とし、要件を固め、最後に設計するという、上流から下流へ一つずつ具体化していく順序が必要になる。","why_asked":"企画プロセスの各工程を入れ替えた選択肢で正しい順序を見分けさせる出題は頻出。特にシステム化構想とシステム化基本方針の前後関係、要件定義と設計の前後関係を混同させやすい。","vs":"システム化基本方針はシステム化構想より後(方向性を受けて具体化する段階)。システム設計は要件定義より後(何が必要かを固めてから中身を決める段階)。","opt":["正解。システム化構想の立案で方向性を定めた後、システム化基本方針で体制やスケジュールを具体化し、個別システムの要件定義を経て、最後に設計へ進む。","要件定義を最初に置くと、経営課題やシステム化の方向性が定まらないまま個別システムの要件を決めることになり、経営課題とずれた要件になりやすい。","システム化基本方針をシステム化構想より先に置くと、方向性が定まらないまま体制やスケジュールを具体化することになり、順序が逆である。","システム設計を最初に置くと、何が必要かという要件が固まらないまま内部構造を決めることになり、後で大きな手戻りが生じる。"],"viz":"<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">企画からシステム設計に至る一般的な流れ</text><rect x=\"8\" y=\"50\" width=\"68\" height=\"50\" rx=\"4\" fill=\"#3b82f6\"/><text x=\"42\" y=\"70\" fill=\"#0d1117\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">システム化</text><text x=\"42\" y=\"84\" fill=\"#0d1117\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">構想</text><text x=\"84\" y=\"80\" fill=\"#8892a4\" font-size=\"16\" text-anchor=\"middle\">→</text><rect x=\"92\" y=\"50\" width=\"68\" height=\"50\" rx=\"4\" fill=\"#3b82f6\"/><text x=\"126\" y=\"70\" fill=\"#0d1117\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">システム化</text><text x=\"126\" y=\"84\" fill=\"#0d1117\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">基本方針</text><text x=\"168\" y=\"80\" fill=\"#8892a4\" font-size=\"16\" text-anchor=\"middle\">→</text><rect x=\"176\" y=\"50\" width=\"68\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.4\"/><text x=\"210\" y=\"70\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">要件</text><text x=\"210\" y=\"84\" fill=\"#8892a4\" font-size=\"10\" text-anchor=\"middle\">定義</text><text x=\"252\" y=\"80\" fill=\"#8892a4\" font-size=\"16\" text-anchor=\"middle\">→</text><rect x=\"260\" y=\"50\" width=\"68\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.4\"/><text x=\"294\" y=\"80\" fill=\"#8892a4\" font-size=\"11\" text-anchor=\"middle\">設計</text><text x=\"170\" y=\"144\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">青色の2つが個別システムの企画段階にあたる</text></svg>"}'),

  ('ap-core-q208', 'システム企画',
   '投資の意思決定における「PBP法(回収期間法)」の考え方として、最も適切なものはどれか。',
   NULL::text,
   '["投資した金額を、その投資によって毎年得られる効果額で割ることで、投資額を回収するまでに要する期間を求め、それを評価の基準とする。","将来にわたって得られる効果額を、金利などを踏まえた割引率を用いてあらためて現在の価値に換算し直したうえで、投資額と比較して評価する。","投資によって生じるリスクの発生確率と影響度を掛け合わせて数値化し、リスクの大きさを評価する。","システムの利用者数と処理件数の見込みから、必要となるサーバー台数や回線容量を見積もる。"]',
   0, '[0]', 'single',
   '{"asked":"PBP法(回収期間法)がどのような考え方で投資を評価する手法かを問う設問。","point":"『投資額を年間の効果額で割って、何年で元が取れるかを見る』のがPBP法。","kid":"PBP法は、投資したお金が何年で回収できるかだけをシンプルに見る方法。回収期間が短いほど、その投資は良い投資だと判断する。","eg":"貯金箱にお小遣いを入れて、毎月決まった額を引き出すとしたら、入れた分を何か月で使い切れるかを数えるようなもの。","terms":[["投資対効果","かけた費用に対して、どれだけの効果(コスト削減や売上増加など)が見込めるかという見積もり"],["回収期間","投資した金額を、得られる効果の累計額が上回るまでに要する期間"]],"think":"なぜ何年で回収できるかという単純な指標が使われるのかがカギ。投資対効果を評価する方法は複数あるが、経営者や現場の担当者にとって元が取れるまで何年かは直感的に理解しやすく、複数の投資案を比較する際の一次的なふるい分けとして使いやすい。そこで、投資額を年間の効果額で割るだけで求められるPBP法が、簡便な評価手法として広く使われている。ただし、この考え方は回収後に生まれる効果や、お金の価値が時間とともに変わることまでは考慮していない点に注意が要る。","why_asked":"PBP法の考え方をDCF法やリスク評価など別の手法と混同させる出題が多い。投資額を年間効果額で割るというシンプルな計算だという点を押さえているかを問う。","vs":"将来の効果額を現在価値に割り引いて評価するのはDCF法(割引キャッシュフロー法)の考え方。PBP法は割り引きを行わず、単純に金額を効果額で割るだけである。","opt":["正解。投資額を年間の効果額で割ることで回収に要する期間を求め、それを評価の基準とする。","将来の効果額を割引率で現在価値に換算するのはDCF法の考え方であり、PBP法はそのような割り引きを行わない。","リスクの発生確率と影響度を掛け合わせて評価するのはリスクマネジメントの考え方であり、投資回収期間の評価とは異なる。","利用者数や処理件数からサーバー台数や回線容量を見積もるのはキャパシティプランニングの考え方であり、投資対効果の評価手法ではない。"]}'),

  ('ap-core-q209', 'システム企画',
   'あるシステムへの投資額が600万円であり、このシステムの導入によって毎年200万円の業務効率化の効果が見込まれるとき、PBP法(回収期間法)によって求められる投資の回収期間として、最も適切なものはどれか。ただし、毎年の効果額は一定であるものとする。',
   NULL::text,
   '["3年","2年","4年","6年"]',
   0, '[0]', 'single',
   '{"asked":"投資額600万円、年間効果額200万円のときのPBP法による回収期間を求める計算問題。","point":"回収期間＝投資額÷年間の効果額。600万円÷200万円/年＝3年。","kid":"毎年200万円ずつ効果(得)が積み上がっていくとして、600万円に達するまで何年かかるかを数える。200万円が3回で600万円になるから3年。","eg":"600個のアメを、1年に200個ずつ配っていくと、3年で配り終わる。それと同じ考え方。","terms":[["回収期間","投資した金額を、得られる効果の累計額が上回るまでに要する期間"]],"calc":"600万円(投資額) ÷ 200万円(年間の効果額)\\n= 3\\n= 回収期間は3年","think":"なぜ割り算一つで回収期間が求まるのかがカギ。毎年の効果額が一定であれば、1年あたり200万円ずつ投資額が回収されていくと考えられる。したがって、投資額600万円が何年分の200万円に相当するかを求めればよく、それは600万円を200万円で割る計算そのものになる。600÷200=3なので、3年で投資額と同じだけの効果が積み上がり、回収が完了する。","why_asked":"PBP法の計算問題は頻出。回収期間＝投資額÷年間効果額という式を、割る順序を間違えずに使えるかを問う。","vs":"投資額を効果額で割る(600÷200)のが正しい順序。効果額を投資額で割る(200÷600)と、1年あたりの回収率のような別の数値になってしまい、年数は求まらない。","opt":["正解。600万円(投資額)を200万円(年間の効果額)で割ると3になる。回収期間は3年である。","年間の効果額を誤って300万円として計算すると生じる値である。","年間の効果額を誤って150万円として計算すると生じる値である。","年間の効果額を誤って100万円として計算すると生じる値である。"]}'),

  ('ap-core-q210', 'システム企画',
   'PBP法(回収期間法)による投資評価の限界として、最も適切なものはどれか。',
   NULL::text,
   '["回収期間の長さだけに着目するため、将来受け取るお金と現在受け取るお金の価値の違い(貨幣の時間的価値)を考慮できない。","計算の過程で投資額そのものを用いることがないため、投資規模の異なる複数の案件同士を並べて公平に比較することができない。","年間の効果額を必要としないため、効果が全く得られない投資案でも回収期間を算出できてしまう。","リスクの発生確率を数値化する手法であるため、確率分布が分からない投資案には適用できない。"]',
   0, '[0]', 'single',
   '{"asked":"PBP法(回収期間法)という投資評価手法が抱える限界・弱点を問う設問。","point":"『将来のお金と今のお金を同じ価値として扱ってしまう』のがPBP法の弱点。この弱点を補うのがDCF法。","kid":"PBP法は何年で元が取れるかしか見ないので、5年後にもらえる100万円も、今日もらえる100万円も同じ扱いにしてしまう。でも本当は、今すぐ使えるお金の方が価値が高い。","eg":"3年後に返すという約束のお金と、今すぐ返すお金では、同じ100万円でも今すぐの方がありがたい。銀行に預ければ利息がつくのと同じ発想。PBP法はこの違いを無視してしまう。","terms":[["貨幣の時間的価値","同じ金額でも、今受け取るお金の方が将来受け取るお金より価値が高いという考え方"],["DCF法","将来のお金を、貨幣の時間的価値を踏まえて現在の価値に割り引いて評価する手法"]],"think":"なぜPBP法だけでは不十分でDCF法も必要になるのかがカギ。PBP法は投資額÷年間効果額という単純な割り算だけで回収期間を求めるため、いつ効果が得られるかという時期の違いを一切考慮しない。しかし本来、同じ100万円でも、今日受け取れる100万円と5年後に受け取る100万円とでは価値が異なる(今のお金は運用して増やせるが、将来のお金はまだ手元にない)。この貨幣の時間的価値を無視したまま回収期間の短さだけで投資を判断すると、実際の価値を見誤ることがある。そこで、将来のお金を現在の価値に割り引いて評価するDCF法が、PBP法を補う手法として使われる。","why_asked":"PBP法の限界を問う設問は、DCF法が必要とされる理由(貨幣の時間的価値)を理解しているかを確認するために出題される。","vs":"投資額を使わない、効果額を必要としない、リスクの確率を扱う、といった記述はいずれもPBP法の実際の計算方法(投資額÷年間効果額)と食い違う誤った説明である。","opt":["正解。回収期間の長さだけに着目するため、貨幣の時間的価値を考慮できない。","PBP法は投資額を年間効果額で割ることで回収期間を求めるため、投資額そのものを計算に用いる。この記述は誤りである。","PBP法は年間の効果額を投資額で割ることで回収期間を求めるため、効果額を必要とする。この記述は誤りである。","PBP法はリスクの発生確率を数値化する手法ではなく、投資額と効果額から回収期間を求める手法である。この記述は誤りである。"]}'),

  ('ap-core-q211', 'システム企画',
   '投資の意思決定における「DCF法(割引キャッシュフロー法)」の考え方として、最も適切なものはどれか。',
   NULL::text,
   '["将来得られるキャッシュフローを、金利などを踏まえた割引率を用いて現在の価値に換算し直したうえで、投資の価値を評価する。","投資した金額を、毎年得られる効果額で割ることで、投資額を回収するまでに要する期間の長さを求め、それを評価の基準とする。","過去の会計期間における実際の収益と費用を比較し、投資が黒字であったかどうかを事後的に確認する。","システムを構成する複数の機器の稼働率を掛け合わせて、システム全体としての稼働率を算出する。"]',
   0, '[0]', 'single',
   '{"asked":"DCF法(割引キャッシュフロー法)がどのような考え方で投資を評価する手法かを問う設問。","point":"『将来のお金を、今の価値に割り引いてから比較する』のがDCF法。","kid":"DCF法は、将来もらえるお金をそのままの金額で数えるのではなく、今の価値に直すといくらかに計算し直してから、投資額と比べる方法。","eg":"5年後に110万円もらえるという話も、今は銀行に預ければ増えることを考えると今の100万円と同じくらいの価値かもしれない。DCF法はこの今の価値に直す計算を行う。","terms":[["割引率","将来のお金を現在の価値に直すときに使う、価値の目減り具合を表す割合"],["キャッシュフロー","一定期間に実際に出入りするお金の流れ"]],"think":"なぜ将来のお金をそのままの金額で扱ってはいけないのかがカギ。今日手元にある100万円は、預金や運用に回せば将来もっと増やせる可能性がある。逆に言えば、将来受け取る100万円は、今日の100万円より価値が低いと考えられる。この違いを無視して将来のキャッシュフローをそのまま合計してしまうと、投資の価値を過大に評価してしまう。そこでDCF法では、将来の各年のキャッシュフローに割引率を掛けて今の価値ならいくらに相当するかへ計算し直してから、投資額と比較する。","why_asked":"DCF法をPBP法や事後の収益確認、稼働率計算など別の考え方と混同させる出題が多い。将来のお金を現在価値に割り引くという核心を問う。","vs":"投資額を年間効果額で割って回収期間を求めるのはPBP法。DCF法は回収期間ではなく、将来のお金を現在価値に割り引いた金額で投資の価値そのものを評価する点が異なる。","opt":["正解。将来のキャッシュフローを割引率で現在価値に換算し直したうえで、投資の価値を評価する。","投資額を年間効果額で割って回収期間を求めるのはPBP法(回収期間法)の考え方であり、DCF法とは異なる。","過去の実績を事後的に確認するのは投資の事後評価にあたり、将来のキャッシュフローを評価するDCF法とは異なる。","機器の稼働率を掛け合わせてシステム全体の稼働率を求めるのは信頼性評価の考え方であり、投資評価の手法ではない。"]}'),

  ('ap-core-q212', 'システム企画',
   'PBP法(回収期間法)とDCF法(割引キャッシュフロー法)の違いに関する記述として、最も適切なものはどれか。',
   NULL::text,
   '["PBP法は貨幣の時間的価値を考慮せずに回収期間の長さで評価するのに対し、DCF法は将来のキャッシュフローを現在価値に割り引いて評価する。","PBP法は将来得られるキャッシュフローを現在価値に割り引いて評価するのに対し、DCF法は回収期間の長さだけを見て評価する、という逆の関係にある。","PBP法とDCF法はいずれも将来のキャッシュフローを現在価値に割り引いて評価する点で共通しており、割引率の算出方法だけが異なる。","PBP法とDCF法はいずれも過去の会計実績をもとに投資の成否を事後的に判定する手法であり、将来の予測は一切行わない。"]',
   0, '[0]', 'single',
   '{"asked":"PBP法とDCF法という二つの投資評価手法の違いを問う設問。","point":"『貨幣の時間的価値を考えないのがPBP法、考えるのがDCF法』という一点で見分ける。","kid":"PBP法は何年で元が取れるかだけを単純に見る方法。DCF法は将来のお金を今の価値に直してから評価する、もう一歩踏み込んだ方法。","eg":"PBP法はお小遣いを何年で使い切るかを数えるだけの単純な数え方。DCF法はそのお小遣いを今の価値に直すといくらかまで考える、もう一段階丁寧な数え方。","terms":[["貨幣の時間的価値","同じ金額でも、今受け取るお金の方が将来受け取るお金より価値が高いという考え方"]],"think":"なぜこの二つの手法を並べて出題されるのかがカギ。両方とも投資額と将来の効果(キャッシュフロー)を比べて投資の妥当性を判断する点は共通しているが、将来の効果額をどう扱うかが決定的に異なる。PBP法は将来の効果額をそのままの金額で扱い、投資額をそれで割るだけなので計算が簡単な一方、貨幣の時間的価値を考慮できない。DCF法は将来の効果額を割引率で現在価値に割り引いてから評価するため、貨幣の時間的価値を反映できるが、割引率の設定など計算はPBP法より複雑になる。この時間的価値を考えるかどうかが両者を分ける核心である。","why_asked":"二つの手法の説明を入れ替えた選択肢や、両方に共通する誤った特徴を挙げる選択肢で、正しい対比を理解しているかを問う。","vs":"割引率を使って現在価値に割り引くのはDCF法だけの特徴であり、PBP法にはこの操作がない。この一点を入れ替えた記述に注意する。","opt":["正解。PBP法は貨幣の時間的価値を考慮せず回収期間の長さで評価し、DCF法は将来のキャッシュフローを現在価値に割り引いて評価する。","PBP法とDCF法の説明が入れ替わっている。現在価値への割り引きを行うのはDCF法であり、PBP法は回収期間の長さだけで評価する。","PBP法は将来のキャッシュフローを割り引く操作を行わないため、両者が同じ考え方であるとする記述は誤りである。","両手法とも投資の意思決定を行う前に将来の効果を予測して評価する手法であり、過去の実績だけを事後的に判定するものではない。"]}'),

  ('ap-core-q213', 'システム企画',
   '情報システムの企画段階で立てられる「要員教育計画」の位置づけとして、最も適切なものはどれか。',
   NULL::text,
   '["新しいシステムを利用者や運用担当者が使いこなせるように、システム化計画の中であらかじめ教育・訓練の内容や時期を計画しておくもの。","システムの内部構造や画面・帳票のレイアウトなど、開発者が参照する技術仕様を具体的に定めたもの。","システム開発を担当するプロジェクトメンバー個々の人件費だけを積算した、開発予算に関する計画。","システムが本番稼働を開始してから実際に発生した障害の対応履歴をひとつずつ記録に残し、再発防止策を検討するためにまとめておく記録。"]',
   0, '[0]', 'single',
   '{"asked":"システム化計画の中に含まれる「要員教育計画」が何を指すかを問う設問。","point":"『新システムを使う人・運用する人が困らないように、教育の内容と時期を前もって決めておく計画』が要員教育計画。","kid":"新しいシステムができても、使う人がその使い方を知らなければ意味がない。だから、システムが完成する前の企画段階で、誰に・いつ・何を教えるかをあらかじめ計画しておく。それが要員教育計画。","eg":"新しい調理器具を買うとき、届く前から使い方の説明書をいつ配るか、試しに使ってみる日をいつ設けるかを決めておくようなもの。届いてから慌てて教えるのでは遅い。","terms":[["システム化計画","システム化構想を受けて、開発体制やスケジュール、投資対効果などを具体化した計画"]],"think":"なぜ企画段階のうちから教育計画を立てておく必要があるのかがカギ。新しいシステムは、稼働を開始した瞬間から利用者や運用担当者がそれを使いこなせなければ、期待した効果が得られない。もし教育をシステム完成後に慌てて考え始めると、教育の準備が間に合わずに稼働が遅れたり、使い方が定着しないまま現場が混乱したりする。そこで、システム化計画の段階からあらかじめ誰に・いつ・何を教えるかを計画に組み込んでおくことで、稼働開始と同時に利用者がスムーズにシステムを使い始められるようにする。","why_asked":"要員教育計画を、技術仕様やコスト計画、障害対応記録といった別の計画・記録と混同させる出題が多い。","vs":"内部構造や画面レイアウトの技術仕様は開発工程で定めるものであり、要員教育計画とは対象が異なる。要員教育計画はあくまで人を育てるための計画である。","opt":["正解。新しいシステムを利用者や運用担当者が使いこなせるよう、教育・訓練の内容や時期をあらかじめ計画しておくものである。","システムの内部構造や画面レイアウトの技術仕様は開発工程で定める内容であり、要員教育計画とは対象が異なる。","プロジェクトメンバーの人件費の積算はコスト管理の一部であり、利用者・運用担当者を育てる要員教育計画とは目的が異なる。","障害対応履歴の記録は稼働後の障害管理の作業であり、企画段階で立てる要員教育計画とは時期も目的も異なる。"]}'),

  ('ap-core-q214', 'システム企画',
   '情報システムを企画する際に配慮すべき「デジタルディバイド」の考え方として、最も適切なものはどれか。',
   NULL::text,
   '["情報技術を利用できる環境や能力の違いによって、人々の間に得られる情報や機会の格差が生じること。","開発するシステムと既存の他システムとの間で、データ形式の違いによって連携がうまくいかないこと。","異なるベンダーの機器を組み合わせた際に、通信規格の違いによって接続できないこと。","システムの利用者数が急増した際に、サーバーの処理能力が追いつかず応答が遅くなること。"]',
   0, '[0]', 'single',
   '{"asked":"システム企画において配慮すべき「デジタルディバイド」という考え方が何を指すかを問う設問。","point":"『情報技術を使える人と使えない・使いにくい人の間で生まれる格差』を指すのがデジタルディバイド。","kid":"パソコンやスマートフォン、インターネットを使いこなせる人と、年齢や環境の事情でうまく使えない人との間に生まれる、情報や機会の差のこと。システムを企画するときは、この差にも配慮する必要がある。","eg":"同じ町内でも、駅前の便利な情報を知っている人と、そもそも情報を得る手段を持たない人がいれば、受けられるサービスの機会に差が出てしまう。それと同じ差が情報技術の利用でも起こる。","terms":[["情報格差","情報技術を利用できるかどうかによって生じる、得られる情報や機会の差"]],"think":"なぜシステム企画の段階でデジタルディバイドへの配慮が必要になるのかがカギ。新しいシステムをインターネットやスマートフォンの利用を前提に設計すると、それらに不慣れな高齢者や、通信環境が十分でない地域の利用者は、他の人と同じサービスを受けられなくなってしまう。これは単なる技術上の課題ではなく、情報技術を利用できる人とできない人との間で得られる機会に差が生じるという、社会的な課題でもある。そのため、システムを企画する段階から、誰もが公平にサービスを受けられるように利用者側の情報技術の利用環境や能力の差にあらかじめ配慮しておく必要がある。","why_asked":"デジタルディバイドという用語を、システム間連携や相互接続性、性能面の課題など、似て非なる技術的な問題と混同させる出題が多い。","vs":"データ形式や通信規格の違いによる技術的な接続の問題や、サーバーの処理能力不足とは異なり、デジタルディバイドは人々の間に生じる情報・機会の格差という社会的な観点の言葉である。","opt":["正解。情報技術を利用できる環境や能力の違いによって、人々の間に得られる情報や機会の格差が生じることを指す。","データ形式の違いによるシステム間連携の問題は技術的な相互運用性の課題であり、人々の間の情報格差を指すデジタルディバイドとは異なる。","通信規格の違いによる機器間の接続の問題は相互接続性の課題であり、デジタルディバイドとは異なる。","サーバーの処理能力不足による応答遅延は性能面の課題であり、人々の間の情報格差を指すデジタルディバイドとは異なる。"]}')

) AS v(source_ref, category_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('ap-core-q215', 'システム監査',
   'システム監査の目的として、最も適切なものはどれか。',
   NULL::text,
   '["情報システムのリスク対策(コントロール)が有効に機能しているか、独立した立場から検証・評価すること", "システムに障害が発生した際に、その原因をすぐに突き止めてプログラムをただちにその場で修正すること", "新しく開発する情報システムの企画を立ち上げ、業務要件をすべて洗い出して定義書として取りまとめること", "稼働中のシステムの処理性能を測定し、レスポンスタイムやスループットの改善を継続的に図ること"]',
   0,
   '[0]',
   'single',
   '{"asked": "システム監査という活動が、そもそも何のために行われるのかを問う設問。", "point": "『リスクに対するコントロール(対策)が有効に機能しているか、独立した立場で検証・評価する』が監査の目的。障害修正や性能改善など『手を動かして直す』活動と混同しない。", "kid": "会社のシステムに『ちゃんとリスク対策ができているか』を、当事者ではない人がチェックする活動。", "eg": "健康診断のようなもの。医者は治療(修正)はせず、体の状態を検査して『異常があるかどうか』を判断するだけ。治療は別の担当(開発チームや運用チーム)が行う。", "terms": [["リスク", "情報漏えいや障害など、システムに起きうる望ましくない事態"], ["コントロール", "リスクを防ぐ・減らすための仕組みやルール(アクセス権限の設定、承認フローなど)"]], "think": "なぜ監査は『直す』のではなく『検証・評価する』にとどまるのかがカギ。もし監査人がその場で修正まで行ってしまうと、自分の直した結果を自分で評価することになり、判断が甘くなる恐れがある。監査は『コントロールが機能しているかどうかを客観的に判断する』ことに専念し、実際の改善(修正)は監査対象の部門が自らの責任で行う。この役割分担があるからこそ、判断の客観性が保たれる。", "why_asked": "システム監査を『バグ探し』や『性能テスト』と同じものだと誤解している受験者が多いため、目的の違いを問う定番の切り口。", "vs": "障害対応や性能改善はシステムの運用・保守の仕事であり、システム監査とは目的も実施者も異なる。", "opt": ["正解。情報システムのリスク対策(コントロール)が有効に機能しているかどうかを、独立した立場から検証・評価することがシステム監査の目的である。", "これは障害対応や保守の仕事であり、システム監査の目的ではない。監査人はその場で修正を行う立場ではない。", "これはシステム企画や要件定義の仕事であり、既に稼働している(または開発中の)システムを検証するシステム監査とは異なる。", "これは性能チューニングやキャパシティ管理の仕事であり、リスクとコントロールを評価するシステム監査の目的ではない。"]}'),
  ('ap-core-q216', 'システム監査',
   'システム監査の進め方に関する考え方として、最も適切なものはどれか。',
   NULL::text,
   '["監査資源には限りがあるため、リスクの大きい領域を重点的に監査対象として選び、優先順位をつけて監査を行う", "監査の公平性を保つため、規模やリスクの大きさに関わらずすべての処理を毎回まったく同じ密度で細部まで調べる", "監査の効率を上げるため、開発チームが行った自己点検の結果を検証せずそのまま監査意見として採用する", "監査の負担を減らすため、過去に指摘のなかったシステムは状況の変化を確認せず今後の監査対象から完全に外す"]',
   0,
   '[0]',
   'single',
   '{"asked": "システム監査を計画するときの基本的な考え方(何を重点的に見るか)を問う設問。", "point": "監査資源(時間や人員)は有限。だから『リスクの大きい所ほど重点的に見る』リスクアプローチが基本。全部を均等に見る、自己点検を鵜呑みにする、過去無指摘だからと対象から外す、はいずれも不適切。", "kid": "限られた時間で全部を同じ濃さで見るのは無理。だから『危なそうな所』から優先して見ていく、という考え方。", "eg": "健康診断で、持病があり数値が悪化している人には詳しい検査を追加し、健康な人には基本項目だけにする。限られた医療資源を、リスクの高い人に重点配分するのと同じ考え方。", "terms": [["監査資源", "監査に使える時間・人員・予算のこと"], ["リスクアプローチ", "リスクの大きさに応じて監査の重点や深さを変える考え方"]], "think": "なぜ全項目を均等に調べないのかがカギ。監査に使える時間や人員は有限で、すべての処理を同じ深さで調べ切ることは現実的に不可能。もし均等に配分すると、本当にリスクの大きい領域(例えば個人情報を扱う機能)にも、リスクの小さい領域(例えば社内掲示板)にも同じ時間しかかけられず、重大な問題を見逃す危険が高まる。だからリスクの大きさに応じて監査の重点を変えるリスクアプローチが基本になる。", "why_asked": "『監査＝全部くまなくチェック』という素朴なイメージのまま出題されると誤答しやすいため、限られた資源をどう配分するかという実務的な考え方を問う。", "vs": "全項目均等チェックは網羅的に見えて実は非効率であり、自己点検の丸のみは独立性を欠く別の問題(監査人の独立性)にあたる。", "opt": ["正解。監査資源には限りがあるため、リスクの大きい領域を重点的に選んで優先順位をつけて監査するリスクアプローチが基本の考え方である。", "全処理を毎回同じ密度で調べることは、限られた監査資源では現実的でなく、かえってリスクの大きい領域への配分が不足する。", "自己点検の結果をそのまま監査意見として採用すると、監査対象部門自身の判断を鵜呑みにすることになり、独立した立場からの検証にならない。", "過去に指摘がなかったことは、その時点でリスクが低かった根拠にはなっても、状況が変わった後も対象から外し続けてよい根拠にはならない。"]}'),
  ('ap-core-q217', 'システム監査',
   'システム監査人が、監査対象となる情報システムの開発を担当したチームとは別の人でなければならない理由として、最も適切なものはどれか。',
   NULL::text,
   '["自分が関わった仕事を自分で評価すると判断が甘くなりやすく、客観的な評価ができなくなるから", "開発チームは技術力が低く、監査に必要な専門的な知識や経験を十分に持っていないから", "開発チームと監査人を兼務させると、監査全体にかかる人件費が余計に増えてしまうから", "法律上、システム監査は必ず外部の監査法人へ委託しなければならないと明確に定められているから"]',
   0,
   '[0]',
   'single',
   '{"asked": "監査人と監査対象(開発チーム)を分ける理由、つまり独立性が必要な理由を問う設問。", "point": "『自分の仕事を自分で評価すると甘くなる』が独立性の根拠。技術力・費用・法律上の義務といった話ではない。", "kid": "自分の宿題を自分で採点したら、多少できていなくても『まあいいか』と甘く付けてしまいがち。それを防ぐ仕組み。", "eg": "自分の書いたテストコードを自分だけでレビューせず、別の人にレビューしてもらうのと同じ理由。書いた本人は『ここは大丈夫なはず』という思い込みがあり、自分のミスに気づきにくい。", "terms": [["独立性", "監査人が監査対象と利害関係を持たず、公正に判断できる立場にあること"], ["利害関係", "評価する側とされる側が同じ、または利益でつながっている状態"]], "think": "なぜ利害関係があると客観的な評価ができなくなるのかがカギ。人は自分が作った物や、自分に近い立場の仕事を評価するとき、無意識に『大きな問題はないはずだ』という前提で見てしまいやすい。開発チーム自身が監査を行うと、自分たちの設計判断やコーディングの甘さを自分たちで指摘することになり、心理的に厳しい評価をしにくい。だから監査人は開発チームと利害関係のない別の立場に置き、指摘すべきことを指摘できる状態を保つ。これが独立性の意味である。", "why_asked": "独立性を『専門知識の有無』や『コストの問題』と取り違える受験者が多いため、本質的な理由(客観性の確保)を問う。", "vs": "専門知識の不足は独立性の問題ではなく監査人の力量の問題であり、混同しない。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">監査人は監査対象(開発チーム)と別の立場に置く</text><line x1=\"170\" y1=\"26\" x2=\"170\" y2=\"122\" stroke=\"#2a2f3f\" stroke-width=\"1.4\" stroke-dasharray=\"4,3\"/><rect x=\"28\" y=\"50\" width=\"112\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.4\"/><text x=\"84\" y=\"71\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">開発チーム</text><text x=\"84\" y=\"87\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">(監査対象)</text><rect x=\"200\" y=\"50\" width=\"112\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><text x=\"256\" y=\"71\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">監査チーム</text><text x=\"256\" y=\"87\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">(独立した立場)</text><path d=\"M198,75 C185,75 155,75 142,75\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.4\" marker-end=\"url(#arrow217)\"/><text x=\"170\" y=\"65\" fill=\"#60a5fa\" font-size=\"9\" text-anchor=\"middle\">検証・評価</text><text x=\"170\" y=\"140\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">利害関係のない別の立場だから、客観的に評価できる</text><defs><marker id=\"arrow217\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#60a5fa\"/></marker></defs></svg>", "opt": ["正解。自分が関わった仕事を自分で評価すると判断が甘くなりやすく客観的な評価ができなくなるため、監査人は開発チームと別の人でなければならない。", "独立性は技術力の高さとは関係がなく、たとえ開発チームが高い技術力を持っていても、自分の仕事を自分で評価する構図である限り客観性は保てない。", "独立性が求められる理由は費用の問題ではなく、評価する側とされる側が同じであることによる客観性の欠如を防ぐためである。", "システム監査を必ず外部の監査法人に委託しなければならないという法律上の一律の義務はなく、社内の独立した部門が監査人を務めることもできる。"]}'),
  ('ap-core-q218', 'システム監査',
   '会社の中に設置された内部監査部門が行う「内部監査」における独立性の考え方として、最も適切なものはどれか。',
   NULL::text,
   '["内部監査部門であっても、監査対象部門から独立した立場・権限を持ち、しがらみに左右されず評価できる体制が必要である", "内部監査は社内の人間が行うため、独立性という考え方はそもそも当てはまらず、外部監査だけに求められる概念にすぎない", "内部監査部門は、監査の効率を優先し、監査対象部門の上司の指示に従って監査結果の内容を調整してよい", "内部監査は監査対象部門と同じ上長のもとで一体的に業務を行うことで、情報共有がしやすくなり望ましい"]',
   0,
   '[0]',
   'single',
   '{"asked": "社内で行う内部監査でも独立性が求められるのか、求められるとしたらどういう形かを問う設問。", "point": "内部監査でも独立性は必要。社内の人間が行うからといって独立性が不要になるわけではなく、監査対象部門からの独立した立場・権限が求められる。", "kid": "同じ会社の中の話でも、『監査する人』と『監査される部門』が上下関係やなれ合いの関係にあってはいけない、ということ。", "eg": "社内のヘルプデスクが自分の所属チームが起こした障害を自分たちで『問題なし』と判定してしまうと信用されないのと同じで、社内の監査でも監査対象からは独立した立場が要る。", "terms": [["内部監査", "組織内部に設置された監査部門が行う監査"], ["外部監査", "監査法人など組織の外部の第三者が行う監査"]], "think": "なぜ社内の監査でも独立性が要るのかがカギ。監査が信頼される根拠は、監査意見が特定の部門の思惑に左右されずに出されていることにある。内部監査部門が監査対象部門と同じ指揮系統に置かれ、その指示で結果を調整できてしまうと、監査結果は『都合よく調整された結果』に見えてしまい、信頼を失う。だから内部監査であっても、監査対象部門から独立した立場・権限(多くは経営者直属など)を確保する必要がある。", "why_asked": "『独立性は外部監査だけの話』という誤解を突く定番の論点。", "vs": "外部監査は組織そのものの外にいる独立性、内部監査は組織内部にいながら監査対象部門からは独立した立場・権限を持つという点で、独立性の確保のしかたが異なる。", "opt": ["正解。内部監査部門であっても監査対象部門から独立した立場・権限を持ち、業務上のしがらみに左右されずに評価できる体制が必要である。", "内部監査であっても、監査意見の信頼性を保つためには独立性の考え方が当てはまる。社内の人間が行うことと独立性が不要になることは別の話である。", "監査対象部門の指示で監査結果を調整してしまうと、監査意見が特定の部門の思惑に左右されることになり、独立性が損なわれる。", "監査対象部門と同じ上長のもとに置かれると、評価する側とされる側の利害関係が近くなり、独立した立場での評価がしにくくなる。"]}'),
  ('ap-core-q219', 'システム監査',
   'システム監査人の独立性を損なう状況の例として、最も適切なものはどれか。',
   NULL::text,
   '["自らが要件定義と設計に深く関与したシステムについて、そのシステムを自分自身が監査人として監査する", "監査人が、監査に着手する前に対象システムの仕様書や過去の障害記録を漏れなくあらかじめ確認しておく", "監査人が、監査で気づいた改善提案を報告書に整理してまとめ、監査対象部門に丁寧に伝える", "監査人が、複数のシステムについて監査の経験を積み重ね、専門的な知識を継続的に高めていく"]',
   0,
   '[0]',
   'single',
   '{"asked": "独立性が損なわれている(問題のある)状況を具体的に見分ける設問。", "point": "『自分が関わったものを自分で監査する』が独立性を損なう典型例。事前の資料確認や改善提案、経験の蓄積は問題ない。", "kid": "自分が作ったものを自分で採点する状況が、独立性が壊れている状態。", "eg": "自分が書いたレポートを自分で『よくできている』と採点するようなもの。採点する人と書いた人が同じでは、評価の意味がなくなる。", "terms": [["利害関係", "評価する側とされる側の間に、公正な判断を妨げるつながりがある状態"]], "think": "なぜ自分が関与したシステムの監査はできないのかがカギ。要件定義や設計に深く関与した人は、そのシステムの判断や設計方針に強い思い入れや思い込みを持ちやすく、問題点があっても『これはこういう意図で作った、問題ない』と自分の判断を正当化してしまいがちである。これは監査人と監査対象の間に利害関係が生まれている状態そのものであり、客観的な評価ができなくなる。一方、事前の資料確認・改善提案・経験の蓄積は、いずれも監査対象システムの開発や運用そのものに監査人が関与しているわけではないため、独立性の問題にはならない。", "why_asked": "独立性を損なう具体的な状況と、独立性とは関係のない通常の監査行為(資料確認・提案・経験)を混同させる出題が定番のため。", "vs": "改善提案を報告書に書くことは監査の正常な業務であり、独立性の問題ではない。独立性が問題になるのは評価する側とされる側が同一人物・同一の利害になっている場合に限られる。", "opt": ["正解。自らが要件定義・設計に深く関与したシステムを自分自身が監査すると、評価する側とされる側が同一人物になり、客観的な判断ができなくなる。", "監査前に仕様書や過去の障害記録を確認しておくことは、監査の質を高めるための通常の準備行為であり、独立性の問題ではない。", "監査で気づいた改善提案を報告書にまとめて伝えることは監査の正常な成果物であり、独立性を損なう行為ではない。", "複数のシステムで監査経験を積み専門知識を高めることは監査人の力量向上であり、独立性とは別の観点である。"]}'),
  ('ap-core-q220', 'システム監査',
   'システム監査における「監査証拠」の説明として、最も適切なものはどれか。',
   NULL::text,
   '["監査人が監査意見を形成するために収集する、客観的な事実に基づく資料や記録のこと", "監査人が長年の経験から抱く、システムに対する主観的な印象や勘のこと", "監査対象部門が作成した報告書のうち、監査人にとって都合のよい記述だけを指すもの", "監査が終了した後に監査対象部門が作成する、改善計画書のこと"]',
   0,
   '[0]',
   'single',
   '{"asked": "監査意見の根拠となる『監査証拠』とは何を指すのかを問う設問。", "point": "監査証拠は『客観的な事実に基づく資料・記録』。監査人の主観的な印象や勘、都合のよい記述の抜き出し、改善計画書とは別物。", "kid": "『なぜそう判断したのか』を人に説明するときに見せられる、客観的な裏付け資料のこと。", "eg": "裁判で判決を下すときに、裁判官の直感ではなく証拠(契約書・記録・証言)に基づいて判断するのと同じ。監査人も『なんとなくそう感じた』ではなく、記録やログといった証拠に基づいて判断する。", "terms": [["監査意見", "監査人が監査の結果として示す、コントロールが有効かどうかの結論"], ["客観的な事実", "誰が見ても確認できる、記録や資料に基づく事実"]], "think": "なぜ監査人の勘や印象では不十分なのかがカギ。監査意見は、監査対象部門や経営層など多くの利害関係者に影響を与える重い判断である。もしその根拠が監査人個人の主観的な印象だけだったら、『なぜそう判断したのか』を第三者が検証できず、監査意見への信頼が成り立たない。そこで監査人は、アクセスログ・承認記録・議事録といった客観的な事実に基づく資料を収集し、それを根拠として監査意見を形成する。この客観的な裏付け資料が監査証拠である。", "why_asked": "監査証拠を『経験や勘』『都合のよい記述』と誤解する受験者が多く、客観性という本質を問う定番の切り口。", "vs": "監査証拠は監査人が『集める』ものであり、監査対象部門が監査後に作る改善計画書(指摘事項への対応)とは時系列も役割も異なる。", "opt": ["正解。監査証拠とは、監査人が監査意見を形成するために収集する、客観的な事実に基づく資料や記録のことである。", "監査人の主観的な印象や勘は、第三者が検証できないため監査証拠にはならない。監査意見は客観的な資料に基づいて形成される必要がある。", "都合のよい記述だけを選んで使うことは、客観性を欠く恣意的な行為であり、監査証拠の考え方に反する。", "改善計画書は、指摘事項を受けて監査対象部門が監査の後に作成するものであり、監査意見の根拠となる監査証拠そのものとは区別される。"]}'),
  ('ap-core-q221', 'システム監査',
   'システム監査人が作成する「監査調書」の役割として、最も適切なものはどれか。',
   NULL::text,
   '["監査の過程で何を確認し、どう判断したかを記録し、監査意見の妥当性を後から検証できるようにすること", "監査対象部門に対して、監査人自身の権限で改善すべき事項を命令として一方的に指示すること", "監査人が個人的に感じた感想や漠然とした印象だけを、公表を前提とせず自由気ままに書き留めておくこと", "監査対象システムのソースコード一式を、そのまま何の目的もなく複製して保管しておくこと"]',
   0,
   '[0]',
   'single',
   '{"asked": "監査調書という記録が、何のために作られるのかを問う設問。", "point": "監査調書は『何を確認し、どう判断したか』を記録し、後から監査意見の妥当性を検証できるようにするためのもの。命令書でも感想文でもソースコードの複製でもない。", "kid": "『どこを見て、何を根拠に、どう判断したか』のメモを残しておく仕組み。", "eg": "実験ノートのようなもの。実験の手順と結果を細かく記録しておけば、後で誰かが『本当にその結論で正しいか』を検証できる。監査調書も同じで、後から監査意見を検証できるようにするための記録。", "terms": [["監査意見", "監査人が示す、コントロールが有効かどうかの結論"], ["妥当性", "判断のプロセスや根拠が筋道立っていて、正しいと言えること"]], "think": "なぜ確認内容や判断の根拠を記録しておく必要があるのかがカギ。監査意見だけを結論として示しても、その意見がどのような確認と根拠に基づいているかが分からなければ、第三者はその意見が妥当かどうかを検証できない。また、監査人自身も後から見直したときに判断の過程を思い出せなくなる。そこで監査の過程で確認した内容・入手した監査証拠・下した判断とその根拠を監査調書として記録しておくことで、監査意見の妥当性を後から追跡・検証できるようにする。", "why_asked": "監査調書を『命令書』や『個人的なメモ』と誤解させる出題が定番のため、記録・検証という本来の役割を問う。", "vs": "監査調書は監査人が監査の過程を記録するものであり、監査対象部門に改善を指示する文書(指摘事項の報告)とは別の文書である。", "opt": ["正解。監査調書は監査の過程で何を確認しどう判断したかを記録し、監査意見の妥当性を後から検証できるようにする役割を持つ。", "監査対象部門への改善指示は監査報告書における指摘事項として伝えるものであり、監査人が一方的に命令する形の文書ではない。", "監査調書は監査意見の根拠を示す記録であり、公表を前提としない個人的な感想文とは異なる、監査の正式な記録である。", "ソースコードそのものの複製保管ではなく、確認した内容や判断の根拠を記録することが監査調書の役割である。"]}'),
  ('ap-core-q222', 'システム監査',
   'システム監査における「予備調査」の位置づけとして、最も適切なものはどれか。',
   NULL::text,
   '["本調査に先立ち、監査対象の業務やシステムの全体像・仕組みを把握し、本調査での重点確認点を見極めるための調査", "監査対象部門への指摘事項を報告書としてすべてとりまとめ、改善を求める監査手続きの最終段階の調査", "監査計画を策定するよりも前の段階として、そもそも監査を実施するかどうか自体を判断するための調査", "本調査がすべて終わった後にあらためて実施し、指摘事項が実際にきちんと改善されたかどうかを確かめるための調査"]',
   0,
   '[0]',
   'single',
   '{"asked": "監査手続きの中で予備調査がどの段階にあり、何のために行うのかを問う設問。", "point": "予備調査は本調査の『前』に行い、全体像を把握して重点箇所を見極めるための調査。指摘のとりまとめや改善確認(フォローアップ)とは別の段階。", "kid": "本格的に細かく調べる前に、まず全体をざっと下見しておく段階。", "eg": "旅行の下見のようなもの。いきなり細部を調べ始めるのではなく、まず全体の地図を頭に入れてから『ここは特に念入りに見よう』という場所を決める。", "terms": [["本調査", "予備調査を踏まえて、重点箇所を詳しく確かめる段階の調査"], ["監査計画", "何を、どの範囲・深さで監査するかをあらかじめ定めたもの"]], "think": "なぜ本調査の前に全体像を把握する段階が要るのかがカギ。監査資源は限られており、リスクの大きい領域を重点的に見るリスクアプローチが基本になる。しかし、どこにリスクが大きいかは、対象の業務やシステムの全体像・仕組みを知らなければ判断できない。いきなり細部から調べ始めると、重点を置くべき箇所を見誤ったまま本調査に入ってしまう恐れがある。そこでまず予備調査で全体像・仕組み・関連資料を把握し、本調査で重点的に確かめるべき点を見極めてから、本調査で詳しく確かめる、という順序をとる。", "why_asked": "予備調査と本調査、フォローアップの順序を入れ替えて出題する定番の引っかけがあるため。", "vs": "指摘事項のとりまとめは本調査の後の報告段階、改善状況の確認はさらに後のフォローアップであり、予備調査(最初の段階)とは時期が異なる。", "opt": ["正解。予備調査は本調査に先立ち、業務やシステムの全体像・仕組み・関連資料を把握して、本調査で重点的に確かめる点を見極めるための調査である。", "指摘事項をまとめる段階は、予備調査・本調査を経た後の報告の段階であり、予備調査そのものではない。", "監査を実施するかどうかの決定は、より前段階の監査計画の策定にあたり、予備調査は監査を実施すると決まった後に行う調査である。", "指摘事項の改善状況を確かめるのはフォローアップであり、本調査より後の段階に行われる。予備調査は本調査より前の段階である。"]}'),
  ('ap-core-q223', 'システム監査',
   'システム監査における「予備調査」と「本調査」の違いを説明したものとして、最も適切なものはどれか。',
   NULL::text,
   '["予備調査は全体像を把握して重点箇所を見極める段階、本調査はその重点箇所を詳しく確かめる段階である", "予備調査は監査対象部門が自ら行うものであり、本調査は監査人が行うという、実施者の違いを表す言葉である", "予備調査は口頭のみで確認を行い、本調査は書面のみで確認を行うという、確認手段の違いを表す言葉である", "予備調査は監査の効果を高めるための単なる演出であり、実務上は省略しても本調査の結果に影響しない"]',
   0,
   '[0]',
   'single',
   '{"asked": "予備調査と本調査、それぞれの段階で行うことの違いを問う設問。", "point": "違いは『調べる深さ』。予備調査は全体像の把握、本調査は重点箇所を詳しく確かめる段階。実施者や確認手段(口頭/書面)の違いではない。", "kid": "予備調査はざっくり全体を見る段階、本調査はそこで決めた重点箇所を細かく確かめる段階。どちらも監査人自身が行う。", "eg": "健康診断で言えば、予備調査は問診票と基本項目のチェック、本調査は問診票で気になった点についての精密検査にあたる。どちらも医師(監査人)が行う。", "terms": [["ヒアリング", "監査対象部門の担当者に直接質問して確認すること"], ["実査", "実際にその場で操作や現物を確認すること"]], "think": "なぜ2段階に分けて調べる深さを変えるのかがカギ。監査資源には限りがあるため、対象のすべてを最初から同じ深さで調べることは非効率であり、リスクの大きい箇所を見逃す恐れもある。そこでまず予備調査で全体像を把握し、リスクが大きく重点的に確かめるべき箇所を絞り込む。その上で本調査では、絞り込んだ重点箇所についてヒアリングや資料確認、必要であれば実際の操作確認(実査)まで行い、詳しく確かめる。この『広く浅く→絞って深く』という2段階の流れが、限られた監査資源を有効に使う工夫になっている。", "why_asked": "予備調査と本調査の違いを『実施者』や『確認手段』のような表面的な違いに矮小化する誤答が定番のため、本質(調べる深さの違い)を問う。", "vs": "実施者はどちらも監査人であり、部門と監査人で分かれているわけではない。確認手段もヒアリング・資料確認・実査など予備調査・本調査どちらでも組み合わせて使われる。", "opt": ["正解。予備調査は全体像を把握して重点箇所を見極める段階、本調査はその重点箇所についてヒアリングや資料確認、必要に応じて実査まで行い詳しく確かめる段階である。", "予備調査・本調査のどちらも監査人が行うものであり、実施者が監査対象部門と監査人とで分かれているわけではない。", "予備調査・本調査のどちらも、ヒアリング・資料確認・実査などの手段を必要に応じて組み合わせて使うものであり、口頭のみ・書面のみと固定されているわけではない。", "予備調査は本調査で重点的に確かめる箇所を見極めるための実質的な調査段階であり、省略すると本調査の的が絞れず監査の質が下がる。"]}'),
  ('ap-core-q224', 'システム監査',
   'システム監査の手続き全体の流れとして、最も適切なものはどれか。',
   NULL::text,
   '["予備調査で全体像を把握し、本調査で重点箇所を確かめ、報告書で指摘を伝え、その後改善状況をフォローアップする", "指摘事項をまず洗い出してから、その原因を探るためにあらためて本調査を行い、最後に予備調査で全体像を確認して終了する", "本調査で重点箇所を確かめてから、あらためて予備調査で全体像を把握し直し、報告を行った時点で監査の役割は完全に終了する", "予備調査と本調査を同時に並行して行い、指摘事項の報告をもって監査は終了し、その後の改善状況は監査人が関与しない"]',
   0,
   '[0]',
   'single',
   '{"asked": "システム監査の一連の手続きが、どのような順序で進むのかを問う設問。", "point": "流れは『予備調査→本調査→報告(指摘)→フォローアップ』の順。本調査を先にする、報告で終わり(フォローアップなし)は誤り。", "kid": "まずざっくり見て(予備調査)、重点箇所を詳しく確かめ(本調査)、結果を伝え(報告)、その後ちゃんと直ったか確認する(フォローアップ)、という4段階。", "eg": "健康診断の一連の流れと同じ。問診(予備調査)、精密検査(本調査)、結果の説明(報告)、再検査で改善したか確認(フォローアップ)という順番を飛ばしたり入れ替えたりしない。", "terms": [["報告", "監査の結果と指摘事項を監査対象部門・経営層に伝える段階"], ["フォローアップ", "指摘した事項が実際に改善されたかどうかを、後日あらためて確認すること"]], "think": "なぜこの4段階の順序が必要なのかがカギ。全体像を知らずに重点箇所は決められないので、予備調査は必ず本調査より前に来る。重点箇所を詳しく確かめた結果がなければ指摘事項は作れないので、本調査は報告より前に来る。そして指摘して終わりにすると、実際に改善されたかどうかが分からないままリスクが放置される恐れがあるため、報告の後にフォローアップを置き、改善状況を確認するところまでを一連の手続きとする。この順序を入れ替えると、根拠のない指摘や、改善されたかどうか誰も確認しない指摘になってしまう。", "why_asked": "手続きの順序を入れ替えたり、フォローアップを省略したりする誤答で全体の流れの理解を問う定番の出題。", "vs": "本調査を予備調査より先に行う、報告をもって監査が完全に終了しフォローアップを行わない、といった選択肢は、いずれもこの一連の流れの前提(全体像の把握が先、指摘後の確認まで含む)に反する。", "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">監査手続きは4段階の順序で進む</text><rect x=\"4\" y=\"55\" width=\"72\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.4\"/><text x=\"40\" y=\"79\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">予備調査</text><rect x=\"92\" y=\"55\" width=\"72\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.4\"/><text x=\"128\" y=\"79\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">本調査</text><rect x=\"180\" y=\"55\" width=\"72\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.4\"/><text x=\"216\" y=\"79\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">報告</text><rect x=\"268\" y=\"55\" width=\"68\" height=\"40\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.4\"/><text x=\"302\" y=\"73\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">フォロー</text><text x=\"302\" y=\"85\" fill=\"#e8eaf0\" font-size=\"8.5\" text-anchor=\"middle\" font-weight=\"600\">アップ</text><path d=\"M76,75 L90,75\" stroke=\"#8892a4\" stroke-width=\"1.4\" marker-end=\"url(#arrow224)\"/><path d=\"M164,75 L178,75\" stroke=\"#8892a4\" stroke-width=\"1.4\" marker-end=\"url(#arrow224)\"/><path d=\"M252,75 L266,75\" stroke=\"#8892a4\" stroke-width=\"1.4\" marker-end=\"url(#arrow224)\"/><text x=\"40\" y=\"110\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">全体像を把握</text><text x=\"128\" y=\"110\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">重点箇所を精査</text><text x=\"216\" y=\"110\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">指摘事項を伝達</text><text x=\"302\" y=\"110\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">改善状況を確認</text><text x=\"170\" y=\"138\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">報告で終わらず、改善されたかまで確かめて完結する</text><defs><marker id=\"arrow224\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs></svg>", "opt": ["正解。予備調査で全体像を把握し、本調査で重点箇所を詳しく確かめ、報告書で指摘事項を伝え、その後改善状況をフォローアップするという順序で進む。", "全体像を把握する前に本調査で重点箇所を絞り込むことはできないため、本調査を予備調査より先に行うことはできない。", "本調査を経ずに重点箇所を確かめることはできず、また報告をもって監査が完全に終了するとフォローアップが行われず、改善状況が確認されないままになる。", "予備調査は本調査で確かめる重点箇所を見極めるための調査であり、同時並行では重点箇所を絞り込めない。また指摘後の改善状況の確認(フォローアップ)を行わないと、指摘が実際に改善されたかが分からないままになる。"]}'),
  ('ap-core-q225', 'システム監査',
   'システム監査で発見した問題点を監査対象部門に「指摘事項」として伝えた後、監査人が行うべきこととして、最も適切なものはどれか。',
   NULL::text,
   '["監査対象部門に改善計画の提出を求め、後日あらためて改善状況を確認するフォローアップを行う", "指摘事項を伝えた時点で監査人の役割は終了し、その後の対応はすべて監査対象部門の裁量に委ねる", "監査人自身が改善策を設計し、監査対象部門に代わってシステムを直接修正する", "指摘事項が正しく伝わったかどうかにかかわらず、次回の監査計画の立案に進む"]',
   0,
   '[0]',
   'single',
   '{"asked": "指摘事項を伝えた後、監査人がさらに何をすべきかを問う設問。", "point": "指摘して終わりではなく、改善計画の提出を求め、後日改善状況を確認する(フォローアップ)まで行うのが監査人の役割。", "kid": "『ここが問題です』と伝えたら、それで終わりではなく、後で『本当に直りましたか』を確認しにいくということ。", "eg": "病院で『この数値が悪いので生活習慣を改善してください』と伝えた後、次の診察で本当に数値が改善したかを確認するのと同じ。伝えっぱなしでは、改善したかどうか誰にも分からない。", "terms": [["フォローアップ", "指摘した事項が実際に改善されたかどうかを、後日あらためて確認すること"], ["改善計画", "指摘事項に対して、いつまでに何を行うかをまとめた対応方針"]], "think": "なぜ指摘して終わりにしてはいけないのかがカギ。監査の目的は、リスクに対するコントロールが有効に機能しているかを検証・評価することだった。指摘した時点では、まだ問題は解決しておらず、リスクはそのまま残っている。もし監査人が指摘だけで役割を終えてしまうと、改善が実行されたかどうかを誰も確認しないまま放置され、リスクが解消されないまま次の監査まで見過ごされる恐れがある。だから監査人は改善計画の提出を求め、後日あらためて改善状況を確認するフォローアップまでを一連の役割として行う。", "why_asked": "『監査＝指摘して終わり』という誤解を突く定番の論点。フォローアップの必要性を問う。", "vs": "監査人自身が改善策を設計し修正まで行うと、独立性(自分の直した結果を自分で評価する構図)が崩れる点で、指摘事項とフォローアップの役割とは別の問題を生む。", "opt": ["正解。監査対象部門に改善計画の提出を求め、後日あらためて改善状況を確認するフォローアップを行うことが、指摘事項を伝えた後の監査人の役割である。", "指摘事項を伝えただけで役割が終わってしまうと、実際に改善されたかどうかを誰も確認しないままになり、リスクが放置される恐れがある。", "監査人自身が改善策を設計し修正まで行うと、自分の直した結果を自分で評価することになり、独立性が損なわれる。改善の実行は監査対象部門の責任で行う。", "指摘事項が正しく伝わったかどうかを確認せずに次の監査計画に進むと、指摘の意図が伝わらないまま放置される恐れがある。"]}'),
  ('ap-core-q226', 'システム監査',
   'システム監査における「フォローアップ」がなぜ必要なのかを説明したものとして、最も適切なものはどれか。',
   NULL::text,
   '["指摘して終わりにすると、改善が実際に実行されたかどうかが分からないまま、リスクが放置される可能性があるから", "フォローアップを行うことによって、監査対象部門の評価が上がるとともに、監査人自身の評価も同時に上がるから", "フォローアップというものは法律で義務づけられた単なる形式的な手続きであり、それ自体に実質的な意味はないから", "フォローアップを行うことによって、監査対象部門が改善計画そのものを立てる手間を省くことができるから"]',
   0,
   '[0]',
   'single',
   '{"asked": "フォローアップという手続きが、なぜ監査に組み込まれているのかを問う設問。", "point": "フォローアップが必要な理由は『指摘して終わりだと改善されたか分からずリスクが放置されるおそれがあるから』。形式的な義務や評価アップが理由ではない。", "kid": "『言っただけ』で終わると、本当に直ったかは誰にも分からないまま。だから後で確かめる、という理由。", "eg": "ダイエットを指導する専門家が、アドバイスをした後に何も確認しなければ、相手が本当に実行したかどうか分からないままになる。だから一定期間後に体重や生活習慣を確認しにいく。フォローアップも同じ考え方。", "terms": [["内部統制", "組織が自らのリスクを管理するために、組織内部に設ける仕組みやルール全体"], ["リスクの放置", "問題点が認識されたのに対応されないまま残り続けること"]], "think": "なぜ確認までしないとリスクが放置されうるのかがカギ。指摘事項を伝えることと、その指摘が実際に改善されることは別の話である。監査対象部門が改善計画を提出しても、人員不足や優先順位の都合で改善が先送りされたり、そのまま忘れられたりすることがありうる。監査人が改善状況を確認しないままでいると、指摘した問題が解決したのか未解決のままなのか、外部からは分からない状態が続く。これはシステム監査の目的である『コントロールが有効に機能しているかの検証・評価』が中途半端なまま終わることを意味する。だから改善が実際に機能しているかを後日確認するフォローアップまで行って、はじめて監査の役割が完結する。", "why_asked": "監査の目的(コントロールの有効性の検証)に立ち返らせ、指摘だけでは目的が達成されないことを理解しているかを問う出題。", "vs": "内部統制は組織自身がリスクを管理する仕組みそのものであり、システム監査はその内部統制が機能しているかどうかを外部・独立の立場から評価する活動である。フォローアップは、この評価を指摘して終わりにせず最後まで完結させるための手続きにあたる。", "opt": ["正解。指摘して終わりにすると、改善が実際に実行されたかどうかが分からないまま、リスクが放置される可能性があるためフォローアップが必要である。", "フォローアップの目的は評価を上げることではなく、指摘した問題が実際に改善されたかどうかを確認し、監査の目的を完結させることにある。", "フォローアップは形式だけの手続きではなく、改善が実際に機能しているかを確かめるという実質的な意味を持つ。", "フォローアップは監査対象部門の手間を省くためのものではなく、改善が実行されたかを監査人が確認するための手続きである。"]}')
) AS v(source_ref, category_name, question_text, code, options, correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
